const GROUPS = 8;
const CARS_PER_GROUP = 18;
const TOTAL_CARS = GROUPS * CARS_PER_GROUP; // 144

const CAR_ALIASES = {
  '718 Cayman': 'Cayman',
  'Cayman': '718 Cayman',
  'Q6': 'Q6 E-Tron',
  'Q6 E-Tron': 'Q6',
  'Optra': 'Optra',
  'Echo': 'Echo',
  'Ram 1500': 'Ram 1500',
  'X7': 'X7',
};
function resolveHistName(name) {
  return CAR_ALIASES[name] || name;
}
function namesMatch(a, b) {
  const ra = resolveHistName(a).toLowerCase();
  const rb = resolveHistName(b).toLowerCase();
  const al = a.toLowerCase();
  const bl = b.toLowerCase();
  return al === bl || al === rb || ra === bl || ra === rb;
}

function genId() {
  return Math.random().toString(36).slice(2, 9);
}

function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function simScore() {
  const w = [20, 22, 20, 14, 10, 6, 4, 2, 1, 1]; // 0 à 9 buts
  function randGoals() {
    const r = Math.random() * 100;
    let cum = 0;
    for (let i = 0; i < w.length; i++) { cum += w[i]; if (r < cum) return i; }
    return 0;
  }
  return { h: randGoals(), a: randGoals() };
}

function createCar(name, group) {
  return { id: genId(), name, group };
}

