  function simTout() {
    setDb(d => {
      const next = JSON.parse(JSON.stringify(d));
      const s = next.seasons[next.currentSeasonIdx];

      LEAGUES.forEach(lName => {
        const l = s.leagues[lName];
        if (!l) return;

        Array.from({ length: GROUPS }, (_, g) => g).forEach(g => {
          if (!l.groupResults[g] || l.groupResults[g].length === 0) {
            const groupCars = l.cars.filter(c => c.group === g);
            l.groupResults[g] = roundRobinMatchups(groupCars);
          }
          l.groupResults[g] = l.groupResults[g].map(m => {
            if (m.homeGoals !== null) return m;
            const sc = simScore(); return { ...m, homeGoals: sc.h, awayGoals: sc.a };
          });
        });

        const qualifiers = [];
        for (let g = 0; g < GROUPS; g++) {
          const groupCars = l.cars.filter(c => c.group === g);
          const matches = l.groupResults[g] || [];
          const standings = computeStandings(groupCars, matches);
          standings.slice(0, 8).forEach((st, rank) => {
            const carObj = l.cars.find(c => c.id === st.id);
            qualifiers.push({ id: st.id, name: carObj.name, groupRank: rank + 1, fromGroup: g, pts: st.pts, gf: st.gf, ga: st.ga, diff: st.gf - st.ga });
          });
        }
        const byRank = {};
        for (let r = 1; r <= 8; r++) byRank[r] = qualifiers.filter(q => q.groupRank === r).sort((a, b) => b.pts - a.pts || b.diff - a.diff || b.gf - a.gf);
        const seeded = [];
        for (let r = 1; r <= 8; r++) byRank[r].forEach(q => seeded.push(q));
        seeded.forEach((q, i) => { q.seed = i + 1; });

        if (seeded.length < 64) return; // pas assez de voitures qualifiées

        const pm = {};
        const mk = (round, bracketPos, homeId, awayId, homeSeed, awaySeed, homeGroup, awayGroup, homeGroupRank, awayGroupRank) => {
          const id = genId();
          pm[id] = { id, round, bracketPos, homeId, awayId, homeSeed, awaySeed, homeGroup, awayGroup, homeGroupRank, awayGroupRank, homeGoals: null, awayGoals: null };
        };
        for (let i = 1; i <= 32; i++) {
          const h = seeded[i-1]; const a = seeded[64-i];
          mk('r1', i, h.id, a.id, h.seed, a.seed, h.fromGroup, a.fromGroup, h.groupRank, a.groupRank);
        }
        for (let i = 1; i <= 16; i++) mk('r2', 32+i, null, null, null, null, null, null, null, null);
        for (let i = 1; i <= 8; i++)  mk('r3', 48+i, null, null, null, null, null, null, null, null);
        for (let i = 1; i <= 4; i++)  mk('qf', 56+i, null, null, null, null, null, null, null, null);
        for (let i = 1; i <= 2; i++)  mk('sf', 60+i, null, null, null, null, null, null, null, null);
        mk('final', 63, null, null, null, null, null, null, null, null);
        l.playoffResults = pm;
        l.playoffSeeds = seeded.map(q => ({ id: q.id, seed: q.seed, groupRank: q.groupRank, fromGroup: q.fromGroup }));

        const roundOrder = ['r1','r2','r3','qf','sf','final'];
        const rounds = [
          { from: 'r1', to: 'r2', fromStart: 1,  toStart: 33 },
          { from: 'r2', to: 'r3', fromStart: 33, toStart: 49 },
          { from: 'r3', to: 'qf', fromStart: 49, toStart: 57 },
          { from: 'qf', to: 'sf', fromStart: 57, toStart: 61 },
          { from: 'sf', to: 'final', fromStart: 61, toStart: 63 },
        ];
        roundOrder.forEach(round => {
          Object.values(l.playoffResults).filter(m => m.round === round && m.homeId && m.homeGoals === null).forEach(m => {
            let h, a;
            do { const r = simScore(); h = r.h; a = r.a; } while (h === a);
            l.playoffResults[m.id] = { ...m, homeGoals: h, awayGoals: a };
          });
          const rDef = rounds.find(r => r.from === round);
          if (!rDef) return;
          const fromMs = Object.values(l.playoffResults).filter(m => m.round === round).sort((a, b) => a.bracketPos - b.bracketPos);
          const toMs = Object.values(l.playoffResults).filter(m => m.round === rDef.to).sort((a, b) => a.bracketPos - b.bracketPos);
          toMs.forEach((tm, i) => {
            const m1 = fromMs[i*2], m2 = fromMs[i*2+1];
            if (!m1 || !m2 || m1.homeGoals === null || m2.homeGoals === null) return;
            const w1Id = m1.homeGoals > m1.awayGoals ? m1.homeId : m1.awayId;
            const w2Id = m2.homeGoals > m2.awayGoals ? m2.homeId : m2.awayId;
            const w1Seed = m1.homeGoals > m1.awayGoals ? m1.homeSeed : m1.awaySeed;
            const w2Seed = m2.homeGoals > m2.awayGoals ? m2.homeSeed : m2.awaySeed;
            const w1Group = m1.homeGoals > m1.awayGoals ? m1.homeGroup : m1.awayGroup;
            const w2Group = m2.homeGoals > m2.awayGoals ? m2.homeGroup : m2.awayGroup;
            const w1GRank = m1.homeGoals > m1.awayGoals ? m1.homeGroupRank : m1.awayGroupRank;
            const w2GRank = m2.homeGoals > m2.awayGoals ? m2.homeGroupRank : m2.awayGroupRank;
            l.playoffResults[tm.id] = { ...tm, homeId: w1Id, awayId: w2Id, homeSeed: w1Seed, awaySeed: w2Seed, homeGroup: w1Group, awayGroup: w2Group, homeGroupRank: w1GRank, awayGroupRank: w2GRank, homeGoals: null, awayGoals: null };
          });
        });

        const finalMatch = Object.values(l.playoffResults).find(m => m.round === 'final');
        if (finalMatch && finalMatch.homeGoals !== null) {
          const champId = finalMatch.homeGoals > finalMatch.awayGoals ? finalMatch.homeId : finalMatch.awayId;
          if (champId) s.champions[lName] = champId;
        }
        const lastPerGroup = [];
        for (let g = 0; g < GROUPS; g++) {
          const groupCars = l.cars.filter(c => c.group === g);
          const matches = l.groupResults[g] || [];
          const standings = computeStandings(groupCars, matches);
          const last = standings[standings.length - 1];
          const carObj = l.cars.find(c => c.id === last?.id);
          if (carObj) lastPerGroup.push(carObj);
        }
        if (lastPerGroup.length > 0) {
          const relMatches = {};
          const rms = roundRobinMatchups(lastPerGroup);
          rms.forEach(m => { m.round = 'relegation'; relMatches[m.id] = m; });
          l.relegationResults = relMatches;
          l.relegationCars = lastPerGroup.map(c => c.id);
          Object.values(l.relegationResults).forEach(m => {
            if (m.homeGoals !== null) return;
            const sc = simScore();
            l.relegationResults[m.id] = { ...m, homeGoals: sc.h, awayGoals: sc.a };
          });
        }
      });

      const succLeague = s.leagues['Successeurs'];
      if (succLeague) {
        if (!succLeague.matches || succLeague.matches.length === 0) succLeague.matches = genRoundRobin(succLeague.cars);
        succLeague.matches = succLeague.matches.map(m => {
          if (m.homeGoals !== null) return m;
          const sc = simScore(); return { ...m, homeGoals: sc.h, awayGoals: sc.a };
        });
      }

      const auxToSim = [...AUXILIARY_LEAGUES.filter(l => l !== 'Successeurs')];
      auxToSim.forEach(lName => {
        const league = s.leagues[lName];
        if (!league?.cars?.length) return;
        if (!league.matches || league.matches.length === 0) league.matches = genRoundRobin(league.cars);
        league.matches = league.matches.map(m => {
          if (m.homeGoals !== null) return m;
          const sc = simScore(); return { ...m, homeGoals: sc.h, awayGoals: sc.a };
        });
      });

      return next;
    });
  }

