  function renameCar(leagueName, carId, newName) {
    updateLeague(leagueName, l => ({
      ...l,
      cars: l.cars.map(c => c.id === carId ? { ...c, name: newName } : c)
    }));
  }

  function renameCarEverywhere(leagueName, carId, oldName, newName) {
    if (!newName || newName.trim() === oldName.trim()) return;
    newName = newName.trim();

    setDb(prev => {
      const next = JSON.parse(JSON.stringify(prev));
      next.seasons.forEach(s => {
        const league = s.leagues[leagueName];
        if (!league) return;
        league.cars.forEach(c => {
          if (c.id === carId) c.name = newName;
        });
      });
      if (!next.histOverrides) next.histOverrides = {};
      if (!next.histOverrides[leagueName]) next.histOverrides[leagueName] = {};
      const existing = Object.entries(next.histOverrides[leagueName]).find(([,v]) => v === oldName);
      if (existing) {
        next.histOverrides[leagueName][existing[0]] = newName;
      } else {
        next.histOverrides[leagueName][oldName] = newName;
      }
      if (!next.nameMap) next.nameMap = {};
      if (!next.nameMap[leagueName]) next.nameMap[leagueName] = {};
      next.nameMap[leagueName][carId] = next.nameMap[leagueName][carId] || oldName;
      return next;
    });
  }

  function exportData() {
    const json = JSON.stringify(db, null, 2);
    const blob = new Blob([json], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url; a.download = `tournoi-voitures-s${currentSeason.season}.json`;
    a.click(); URL.revokeObjectURL(url);
  }

  function importData(e) {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = ev => {
      try {
        const parsed = JSON.parse(ev.target.result);
        setDb(parsed);
      } catch { alert("Fichier JSON invalide"); }
    };
    reader.readAsText(file);
  }

  function resetData() {
    loadedForNotifs.current = false;
    const fresh = { 
      seasons: [], 
      currentSeasonIdx: 0, 
      photos: db.photos || {}, 
      brands: db.brands || {},
      histOverrides: db.histOverrides || {},
      nameMap: db.nameMap || {}
    };
    const newSeason = initSeason(33);
    LEAGUES.forEach(l => {
      const prevCars = db.seasons[db.currentSeasonIdx]?.leagues[l]?.cars.map(c => ({ id: c.id, name: c.name })) || [];
      if (prevCars.length > 0) newSeason.leagues[l] = initLeague(l, prevCars);
    });
    AUXILIARY_LEAGUES.forEach(l => {
      const prevCars = db.seasons[db.currentSeasonIdx]?.leagues[l]?.cars || [];
      if (prevCars.length > 0) newSeason.leagues[l] = initAuxLeague(l, prevCars);
    });
    fresh.seasons = [newSeason];
    storageSave(fresh);
    setDb(fresh);
  }

  function getLeague(l) { return currentSeason.leagues[l]; }
  function getCar(l, id) { return getLeague(l)?.cars?.find(c => c.id === id); }
  function getGroupCars(l, g) { return getLeague(l)?.cars?.filter(c => c.group === g) || []; }
  function getGroupMatches(l, g) { return getLeague(l)?.groupResults?.[g] || []; }
  function getGroupStandings(l, g) { return computeStandings(getGroupCars(l, g), getGroupMatches(l, g)); }

  function getHistLeague(leagueName) {
    const overrides = db.histOverrides?.[leagueName] || {};
    const base = HISTORICAL_DATA.historicalBonus[leagueName] || [];
    return base.map(car => {
      const newName = overrides[car.name];
      return newName ? { ...car, name: newName } : car;
    });
  }

  function computeAllSeasonsBonus(leagueName) {
    const totalMap = {}; // carId → { name, total, bySeason }
    const nameMap = db.nameMap?.[leagueName] || {};

    const currentLeague = currentSeason.leagues[leagueName];
    if (currentLeague) {
      currentLeague.cars.forEach(car => {
        if (!totalMap[car.id]) {
          totalMap[car.id] = { id: car.id, name: car.name, total: 0, bySeason: {} };
        }
      });
    }

    db.seasons.forEach(s => {
      const bonus = computeBonusPoints(s, leagueName);
      const league = s.leagues[leagueName];
      Object.entries(bonus).forEach(([id, pts]) => {
        const car = league?.cars.find(c => c.id === id);
        const name = car?.name || id;
        if (!totalMap[id]) totalMap[id] = { id, name, total: 0, bySeason: {}, appChampions: [], appRelegated: [] };
        totalMap[id].total += pts;
        totalMap[id].bySeason[`app-S${s.season}`] = pts;
        totalMap[id].name = name;
      });
      LEAGUES.forEach(l => {
        if (l !== leagueName) return;
        const champId = s.champions?.[l];
        const relId = s.relegated?.[l];
        if (champId) {
          if (!totalMap[champId]) { const car = league?.cars.find(c => c.id === champId); totalMap[champId] = { id: champId, name: car?.name || champId, total: 0, bySeason: {}, appChampions: [], appRelegated: [] }; }
          if (!totalMap[champId].appChampions) totalMap[champId].appChampions = [];
          totalMap[champId].appChampions.push(s.season);
          totalMap[champId].bySeason[`app-S${s.season}`] = totalMap[champId].bySeason[`app-S${s.season}`] || 0;
        }
        if (relId) {
          if (!totalMap[relId]) { const car = league?.cars.find(c => c.id === relId); totalMap[relId] = { id: relId, name: car?.name || relId, total: 0, bySeason: {}, appChampions: [], appRelegated: [] }; }
          if (!totalMap[relId].appRelegated) totalMap[relId].appRelegated = [];
          totalMap[relId].appRelegated.push(s.season);
          totalMap[relId].bySeason[`app-S${s.season}`] = totalMap[relId].bySeason[`app-S${s.season}`] || 0;
        }
      });
    });

    const histLeague = getHistLeague(leagueName);
    histLeague.forEach(histCar => {
      const match = Object.values(totalMap).find(e => {
        const origName = nameMap[e.id] || e.name;
        return namesMatch(origName, histCar.name) || namesMatch(e.name, histCar.name);
      });
      if (match) {
        Object.entries(histCar.bySeason).forEach(([s, pts]) => {
          match.bySeason[`hist-S${s}`] = pts;
          match.total += pts;
        });
        match.histChampions = histCar.champions || [];
        match.histRelegated = histCar.relegated || [];
      } else {
        totalMap[`hist-${histCar.name}`] = {
          id: `hist-${histCar.name}`,
          name: histCar.name,
          histLeagueName: leagueName,
          total: histCar.total,
          bySeason: Object.fromEntries(Object.entries(histCar.bySeason).map(([s,p]) => [`hist-S${s}`, p])),
          histChampions: histCar.champions || [],
          histRelegated: histCar.relegated || [],
          historicalOnly: true
        };
      }
    });

    return Object.values(totalMap).sort((a, b) => b.total - a.total);
  }

  function Dashboard() {
    return (
      <div>
        <div className="section-title">Tableau de Bord — Saison {currentSeason.season}</div>
        <div style={{ display:'flex',flexDirection:'column',gap:16 }}>
          {LEAGUES.map(l => {
            const champId = currentSeason.champions[l];
            const relId = currentSeason.relegated[l];
            const champ = champId ? getCar(l, champId) : null;
            const rel = relId ? getCar(l, relId) : null;
            const league = getLeague(l);
            const allMatches = Object.values(league.groupResults || {}).flat();
            const played = allMatches.filter(m => m.homeGoals !== null).length;
            const total = allMatches.length;
            const pct = total > 0 ? Math.round(played / total * 100) : 0;

            const quals = computeQualifications(l);
            const zCar = quals.Z.size > 0
              ? league.cars.find(c => quals.Z.has(c.id))
              : null;

            const bonus = computeBonusPoints(currentSeason, l);
            const bonusEntries = Object.entries(bonus)
              .map(([id, pts]) => ({ id, pts, car: getCar(l, id) }))
              .filter(e => e.car && e.pts > 0)
              .sort((a, b) => b.pts - a.pts)
              .slice(0, 5);

            return (
              <div key={l} className="card">
                <div className="card-header">
                  <div className="card-title">{l}</div>
                  <div style={{ flex:1 }} />
                  <div style={{ display:'flex',alignItems:'center',gap:8 }}>
                    <div style={{ width:80,height:6,background:'var(--dark3)',borderRadius:3,overflow:'hidden' }}>
                      <div style={{ width:`${pct}%`,height:'100%',background:pct === 100 ? 'var(--green)' :'var(--gold)',borderRadius:3,transition:'width 0.3s' }} />
                    </div>
                    <span className="text-dim" style={{ fontSize:11 }}>{played}/{total} ({pct}%)</span>
                  </div>
                </div>
                <div className="card-body" style={{ display:'flex',flexDirection:'column',gap:12 }}>

                  {/* Champion playoff — pleine largeur en haut */}
                  <div style={{ background:'var(--dark3)',borderRadius:4,padding:10,display:'flex',flexDirection:'column',alignItems:'center' }}>
                    <div style={{ fontSize:10,color:'var(--gold-dim)',fontFamily:"'Bebas Neue',sans-serif",letterSpacing:2,marginBottom:8,alignSelf:'flex-start' }}>🏆 Champion Playoff</div>
                    {champ ? (
                      <>
                        <div style={{ width:'100%',borderRadius:6,overflow:'hidden',background:'var(--dark2)',border:'2px solid var(--gold-dim)',marginBottom:8,cursor:'pointer' }}
                          onClick={() => openProfileCar({ leagueName: l, carId: champId })}>
                          {getCarPhoto(champId)
                            ? <img src={getCarPhoto(champId)} alt="" style={{ width:'100%',height:'auto',display:'block' }} />
                            : <div style={{ height:180,display:'flex',alignItems:'center',justifyContent:'center',fontSize:64 }}>🚗</div>}
                        </div>
                        <span style={{ fontFamily:"'Bebas Neue',sans-serif",fontSize:20,color:'var(--gold)',letterSpacing:2,textAlign:'center' }}>{champ.name}</span>
                        {getCarBrand(champId) && (
                          <span style={{ fontSize:13,color:'var(--text-dim)',textAlign:'center',marginTop:2 }}>{getCarBrand(champId)}</span>
                        )}
                        <button className="btn btn-dark btn-sm" style={{ marginTop:8,fontSize:11 }}
                          onClick={() => setBrandModal({ carId: champId, carName: champ.name, photo: getCarPhoto(champId) })}>
                          {!isPublicMode && <>✏️ {getCarBrand(champId) ? 'Modifier' : 'Ajouter la marque'}</>}
                        </button>
                      </>
                    ) : (
                      <>
                        <div style={{ width:'100%',height:120,borderRadius:6,background:'var(--dark2)',display:'flex',alignItems:'center',justifyContent:'center',border:'1px dashed var(--border)',marginBottom:8 }}>
                          <span style={{ fontSize:48,opacity:0.3 }}>🏆</span>
                        </div>
                        <span className="text-dim" style={{ fontSize:12,textAlign:'center' }}>Playoffs non terminés</span>
                      </>
                    )}
                  </div>

                  {/* Z et Relégué — côte à côte */}
                  <div style={{ display:'grid',gridTemplateColumns:'1fr 1fr',gap:12 }}>

                    {/* Z — Meilleur de la ligue */}
                    <div style={{ background:'var(--dark3)',borderRadius:4,padding:10,display:'flex',flexDirection:'column',alignItems:'center' }}>
                      <div style={{ fontSize:10,color:'var(--gold-dim)',fontFamily:"'Bebas Neue',sans-serif",letterSpacing:2,marginBottom:8,alignSelf:'flex-start' }}>
                        <span style={{ background:'#c9a84c',color:'#000',borderRadius:2,padding:'0 4px',fontSize:10,marginRight:4 }}>Z</span>
                        Meilleur
                      </div>
                      {zCar ? (
                        <div style={{ display:'flex',flexDirection:'column',alignItems:'center',gap:6,cursor:'pointer',width:'100%' }}
                          onClick={() => openProfileCar({ leagueName: l, carId: zCar.id })}>
                          <div style={{ width:'100%',borderRadius:5,overflow:'hidden',background:'var(--dark2)',border:'1px solid var(--gold-dim)',display:'flex',alignItems:'center',justifyContent:'center' }}>
                            {getCarPhoto(zCar.id)
                              ? <img src={getCarPhoto(zCar.id)} alt="" style={{ width:'100%',height:'auto',maxHeight:200,objectFit:'contain',display:'block' }} />
                              : <div style={{ height:100,display:'flex',alignItems:'center',justifyContent:'center',fontSize:28 }}>🚗</div>}
                          </div>
                          <span style={{ fontFamily:"'Bebas Neue',sans-serif",fontSize:13,color:'var(--gold)',letterSpacing:1,textAlign:'center',lineHeight:1.2 }}>{zCar.name}</span>
                        </div>
                      ) : (
                        <span className="text-dim" style={{ fontSize:11 }}>Non terminé</span>
                      )}
                    </div>

                    {/* Relégué */}
                    <div style={{ background:'var(--dark3)',borderRadius:4,padding:10,display:'flex',flexDirection:'column',alignItems:'center' }}>
                      <div style={{ fontSize:10,color:'#e74c3c',fontFamily:"'Bebas Neue',sans-serif",letterSpacing:2,marginBottom:8,alignSelf:'flex-start' }}>⬇ Relégué</div>
                      {rel ? (
                        <div style={{ display:'flex',flexDirection:'column',alignItems:'center',gap:6,cursor:'pointer',width:'100%' }}
                          onClick={() => openProfileCar({ leagueName: l, carId: relId })}>
                          <div style={{ width:'100%',borderRadius:5,overflow:'hidden',background:'var(--dark2)',border:'1px solid rgba(231,76,60,0.4)',display:'flex',alignItems:'center',justifyContent:'center' }}>
                            {getCarPhoto(relId)
                              ? <img src={getCarPhoto(relId)} alt="" style={{ width:'100%',height:'auto',maxHeight:200,objectFit:'contain',display:'block' }} />
                              : <div style={{ height:100,display:'flex',alignItems:'center',justifyContent:'center',fontSize:28 }}>🚗</div>}
                          </div>
                          <span style={{ fontFamily:"'Bebas Neue',sans-serif",fontSize:13,color:'#e74c3c',letterSpacing:1,textAlign:'center',lineHeight:1.2 }}>{rel.name}</span>
                        </div>
                      ) : (
                        <span className="text-dim" style={{ fontSize:11 }}>Non terminé</span>
                      )}
                    </div>
                  </div>

                  {/* Top 5 pts annexes cumulatif — snapshot fin de saison */}
                  <div style={{ background:'var(--dark3)',borderRadius:4,padding:10 }}>
                    <div style={{ fontSize:10,color:'var(--gold-dim)',fontFamily:"'Bebas Neue',sans-serif",letterSpacing:2,marginBottom:8 }}>🏆 Top 5 Pts Annexes — Total Cumulatif</div>
                    {(() => {
                      const prevIdx = db.currentSeasonIdx > 0 ? db.currentSeasonIdx - 1 : 0;
                      const snap = db.seasons[prevIdx]?.bonusSnapshot?.[l];
                      if (!snap || snap.length === 0) return <span className="text-dim" style={{ fontSize:12 }}>Aucune donnée</span>;
                      return (
                        <div style={{ display:'flex',flexDirection:'column',gap:5 }}>
                          {snap.map((e, i) => (
                            <div key={e.name} style={{ display:'flex',alignItems:'center',gap:8,cursor:e.id ? 'pointer' :'default' }}
                              onClick={() => { if (e.id) openProfileCar({ leagueName: l, carId: e.id }); }}>
                              <span style={{ color:'var(--gold-dim)',fontSize:11,width:16,textAlign:'right',flexShrink:0 }}>{i + 1}.</span>
                              <CarThumb photo={getCarPhoto(e.id) || getCarPhotoByName(e.name)} />
                              <span style={{ fontSize:12,flex:1,fontWeight:600 }}>{e.name}</span>
                              <span style={{ fontFamily:"'Bebas Neue',sans-serif",fontSize:16,color:'var(--gold)' }}>{e.pts}</span>
                            </div>
                          ))}
                        </div>
                      );
                    })()}
                  </div>

                </div>
              </div>
            );
          })}
          {/* Promus Successeurs → Ligues Principales */}
          {(() => {
            const succLeague = currentSeason.leagues['Successeurs'];
            const succCars = succLeague?.cars || [];
            const succPlayed = succLeague?.matches || [];
            if (succCars.length === 0) return null;

            const succStandings = succCars.map(car => {
              const cm = succPlayed.filter(m => m.homeId === car.id || m.awayId === car.id);
              let w = 0, d = 0, gf = 0, ga = 0;
              cm.forEach(m => {
                if (m.homeGoals === null) return;
                const isHome = m.homeId === car.id;
                const f = isHome ? m.homeGoals : m.awayGoals;
                const a = isHome ? m.awayGoals : m.homeGoals;
                gf += f; ga += a;
                if (f > a) w++; else if (f === a) d++;
              });
              return { ...car, pts: w * 3 + d, diff: gf - ga, gf };
            }).sort((a, b) => b.pts - a.pts || b.diff - a.diff || b.gf - a.gf);

            const top4 = succStandings.slice(0, 4);
            const anyPlayed = succPlayed.length > 0;
            const promotions = db.succPromotions || {};

            return (
              <div className="card">
                <div className="card-header">
                  <div className="card-title">🔺 Promus Successeurs → Ligues Principales (S{currentSeason.season + 1})</div>
                </div>
                <div className="card-body">
                  {!anyPlayed ? (
                    <span className="text-dim" style={{ fontSize:12 }}>Aucun match joué en Successeurs</span>
                  ) : (
                    <div style={{ display:'grid',gridTemplateColumns:'repeat(2,1fr)',gap:12 }}>
                      {top4.map((car, i) => {
                        const photo = getCarPhoto(car.id);
                        const destLeague = promotions[car.id] || '';
                        return (
                          <div key={car.id} style={{ background:'var(--dark3)',borderRadius:6,overflow:'hidden',border:'1px solid rgba(39,174,96,0.4)' }}>
                            {/* Photo */}
                            <div style={{ position:'relative',height:140,background:'var(--dark2)' }}>
                              {photo
                                ? <img src={photo} alt="" style={{ width:'100%',height:'100%',objectFit:'cover' }} />
                                : <div style={{ height:'100%',display:'flex',alignItems:'center',justifyContent:'center',fontSize:56 }}>🚗</div>}
                              <div style={{ position:'absolute',top:8,left:8,background:'rgba(39,174,96,0.9)',borderRadius:4,padding:'2px 8px',fontFamily:"'Bebas Neue',sans-serif",fontSize:16,color:'#000' }}>#{i + 1}</div>
                              <div style={{ position:'absolute',top:8,right:8,background:'rgba(0,0,0,0.7)',borderRadius:4,padding:'2px 8px',fontFamily:"'Bebas Neue',sans-serif",fontSize:14,color:'var(--gold)' }}>{car.pts} pts</div>
                            </div>
                            {/* Info */}
                            <div style={{ padding:'10px 12px' }}>
                              <div style={{ fontWeight:700,fontSize:16,color:'var(--text)',marginBottom:8 }}>{car.name}</div>
                              <select
                                value={destLeague}
                                onChange={e => {
                                  setDb(prev => ({ ...prev, succPromotions: { ...(prev.succPromotions || {}), [car.id]: e.target.value } }));
                                }}
                                style={{ width:'100%',background:destLeague ? 'rgba(39,174,96,0.15)' :'var(--dark2)',border:`1px solid ${destLeague ? 'var(--green)' :'var(--border)'}`,borderRadius:4,padding:'6px 8px',color:destLeague ? 'var(--green)' :'var(--text-dim)',fontFamily:"'Bebas Neue',sans-serif",fontSize:14,letterSpacing:1 }}>
                                <option value="">— Choisir la ligue —</option>
                                {LEAGUES.map(l => {
                                  const alreadyChosen = top4.some(other => other.id !== car.id && promotions[other.id] === l);
                                  return <option key={l} value={l} disabled={alreadyChosen}>{l}{alreadyChosen ? ' ✗' : ''}</option>;
                                })}
                              </select>
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  )}
                </div>
              </div>
            );
          })()}
        </div>
      </div>
    );
  }

  function GroupesView() {
    const league = getLeague(leagueTab);
    const matches = getGroupMatches(leagueTab, activeGroup);
    const standings = getGroupStandings(leagueTab, activeGroup);
    const groupCars = getGroupCars(leagueTab, activeGroup);
    const [openDay, setOpenDay] = useState(null);

    useEffect(() => {
      if (!league.groupResults[activeGroup]) {
        getOrCreateGroupMatches(leagueTab, activeGroup);
      }
    }, [leagueTab, activeGroup]);

    useEffect(() => {
      if (matches.length === 0) return;
      const days = [...new Set(matches.map(m => m.day))].sort((a, b) => a - b);
      const firstIncomplete = days.find(d => matches.filter(m => m.day === d).some(m => m.homeGoals === null));
      setOpenDay(prev => prev === null ? (firstIncomplete ?? days[days.length - 1]) : prev);
    }, [matches.length]);

    const totalMatches = matches.length;
    const playedMatches = matches.filter(m => m.homeGoals !== null).length;
    const pct = totalMatches > 0 ? Math.round(playedMatches / totalMatches * 100) : 0;
    const days = [...new Set(matches.map(m => m.day))].sort((a, b) => a - b);
    const nextUnplayedDay = days.find(d => matches.filter(m => m.day === d).some(m => m.homeGoals === null));

    return (
      <div>
        <div className="group-tabs">
          {Array.from({ length: GROUPS }, (_, i) => (
            <button key={i} className={`group-tab ${activeGroup === i ? 'active' : ''}`}
              onClick={() => { setActiveGroup(i); setOpenDay(null); }}>
              Groupe {i + 1}
            </button>
          ))}
        </div>

        <div className="sim-bar">
          <span className="text-dim font-bebas" style={{ fontSize:13,marginRight:4 }}>Simulation:</span>
          <button className="btn btn-sm btn-sim"
            style={{ opacity:nextUnplayedDay === undefined ? 0.4 :1 }}
            style={{ display: isPublicMode ? 'none' : undefined }} onClick={() => { if(!isPublicMode){ simulateDay(leagueTab, activeGroup); setOpenDay(nextUnplayedDay); } }}>
            ▶ Journée {(nextUnplayedDay ?? '—')} (9 matchs)
          </button>
          <button className="btn btn-sm btn-sim-all" style={{ display: isPublicMode ? 'none' : undefined }} onClick={() => { if(!isPublicMode) simulateGroup(leagueTab, activeGroup); }}>
            ⚡ Groupe complet
          </button>
          <button className="btn btn-sm" style={{ background:'rgba(155,89,182,0.15)',border:'1px solid rgba(155,89,182,0.4)',color:'#a569bd' }}
            style={{ display: isPublicMode ? 'none' : undefined }} onClick={() => { if(!isPublicMode) simulateLeagueComplete(leagueTab); }}>
            ⚡⚡ Toute la ligue
          </button>
          <span className="text-dim" style={{ fontSize:12,marginLeft:8 }}>
            {playedMatches}/{totalMatches} matchs ({pct}%)
          </span>
        </div>

        <div className="grid-2">
          {/* Classement */}
          {/* Classement */}
          <div className="card">
            <div className="card-header"><div className="card-title">Classement — Groupe {activeGroup + 1}</div></div>
            <div className="card-body" style={{ padding:0 }}>
              {(() => {
                const quals = computeQualifications(leagueTab);
                return (
                  <div>
                      {standings.map((s, i) => {
                        const borderColor = i < 8 ? 'var(--green)' : i < 10 ? 'var(--gold-dim)' : i === standings.length-1 ? '#e74c3c' : 'transparent';
                        const photo = getCarPhoto(s.id);
                        const badge = quals.Z.has(s.id) ? { label:'Z', bg:'#c9a84c', color:'#000' }
                                    : quals.Y.has(s.id) ? { label:'Y', bg:'#27ae60', color:'#fff' }
                                    : quals.X.has(s.id) ? { label:'X', bg:'#2980b9', color:'#fff' }
                                    : quals.P.has(s.id) ? { label:'P', bg:'#16a085', color:'#fff' }
                                    : quals.ELIM.has(s.id) ? { label:'!', bg:'#e74c3c', color:'#fff' }
                                    : getCarMovement(s.id, leagueTab) === 'promoted' ? { label:'▲ PROMU', bg:'rgba(39,174,96,0.25)', color:'var(--green)' }
                                    : getCarMovement(s.id, leagueTab) === 'relegated' ? { label:'⬇ RELÉGUÉ', bg:'rgba(192,57,43,0.25)', color:'#e74c3c' }
                                    : null;
                        const prevRank = (() => {
                          if (!prevSeason) return null;
                          const prevLeague = prevSeason.leagues[leagueTab];
                          if (!prevLeague) return null;
                          const prevCars = prevLeague.cars || [];
                          const prevMatches = prevLeague.groupResults?.[activeGroup] || [];
                          const prevGroupCars = prevCars.filter(c => c.group === activeGroup);
                          if (prevGroupCars.length === 0) return null;
                          const prevStandings = prevGroupCars.map(car => {
                            const cm = prevMatches.filter(m => m.homeId === car.id || m.awayId === car.id);
                            let w = 0, d = 0, gf = 0, ga = 0;
                            cm.forEach(m => { if (m.homeGoals === null) return; const isHome = m.homeId === car.id; const f = isHome ? m.homeGoals : m.awayGoals; const a = isHome ? m.awayGoals : m.homeGoals; gf += f; ga += a; if (f > a) w++; else if (f === a) d++; });
                            return { id: car.id, pts: w * 3 + d, diff: gf - ga, gf };
                          }).sort((a, b) => b.pts - a.pts || b.diff - a.diff || b.gf - a.gf);
                          const idx = prevStandings.findIndex(c => c.id === s.id);
                          return idx >= 0 ? idx + 1 : null;
                        })();
                        const rankDiff = prevRank !== null ? prevRank - (i + 1) : null;
                        return (
                          <LeaderboardRow key={s.id}
                            rank={i+1} rankDiff={rankDiff}
                            carId={s.id} leagueName={leagueTab}
                            name={s.name} photo={photo} badge={badge}
                            pts={s.pts} w={s.w} d={s.d} l={s.l}
                            gf={s.gf} ga={s.ga} gp={s.gp}
                            borderColor={borderColor}
                            onClick={() => openProfileCar({ leagueName: leagueTab, carId: s.id })}
                          />
                        );
                      })}
                  </div>
                );
              })()}
              <div style={{ padding:'8px 12px',fontSize:11,display:'flex',gap:8,flexWrap:'wrap',color:'var(--text-dim)',alignItems:'center' }}>
                <span><span style={{ color:'var(--green)',marginRight:3 }}>■</span>Playoffs</span>
                <span><span style={{ color:'var(--gold)',marginRight:3 }}>■</span>Pts annexes</span>
                <span><span style={{ color:'#e74c3c',marginRight:3 }}>■</span>Barrage</span>
                <span style={{ marginLeft:4,display:'flex',gap:5 }}>
                  {[['X','#2980b9','#fff'],['P','#16a085','#fff'],['Y','#27ae60','#fff'],['Z','#c9a84c','#000'],['!','#e74c3c','#fff']].map(([l,bg,c]) => (
                    <span key={l} style={{ background:bg,color:c,borderRadius:3,padding:'0 5px',fontSize:10,fontFamily:"'Bebas Neue',sans-serif" }}>{l}</span>
                  ))}
                </span>
                <span style={{ marginLeft:'auto',fontSize:10 }}>← glisser →</span>
              </div>
            </div>
          </div>

          {/* Matchs par journée — accordion */}
          <div className="card">
            <div className="card-header">
              <div className="card-title">Matchs — Groupe {activeGroup + 1}</div>
              <span className="text-dim" style={{ fontSize:11,marginLeft:'auto' }}>17 journées · 9 matchs chacune</span>
            </div>
            <div className="card-body" style={{ maxHeight:600,overflowY:'auto',padding:'6px' }}>
              {matches.length === 0 && <div className="text-dim text-center" style={{ padding:24 }}>Chargement...</div>}
              {days.map(day => {
                const dayMatches = matches.filter(m => m.day === day);
                const dayPlayed = dayMatches.filter(m => m.homeGoals !== null).length;
                const dayComplete = dayPlayed === dayMatches.length;
                const isOpen = openDay === day;
                return (
                  <div key={day} style={{ marginBottom:3 }}>
                    {/* Journée header */}
                    <div onClick={() => {
  const scrollY = window.scrollY;
  document.body.style.position = 'fixed';
  document.body.style.top = `-${scrollY}px`;
  document.body.style.width = '100%';
  setOpenDay(isOpen ? null : day);
  requestAnimationFrame(() => {
    document.body.style.position = '';
    document.body.style.top = '';
    document.body.style.width = '';
    window.scrollTo(0, scrollY);
  });
}}
                      style={{
                        display:'flex',alignItems:'center',gap:8,padding:'7px 10px',cursor:'pointer',borderRadius:isOpen ? '3px 3px 0 0' :3,background:isOpen ? 'rgba(201,168,76,0.1)' :'var(--dark3)',border:`1px solid ${isOpen ? 'var(--gold-dim)' :'var(--border)'}`,transition:'all 0.15s',userSelect:'none'
                      }}>
                      <span style={{ fontFamily:"'Bebas Neue',sans-serif",letterSpacing:2,fontSize:14,color:isOpen ? 'var(--gold)' :'var(--text-dim)' }}>
                        Journée {day}
                      </span>
                      <span style={{ flex:1 }} />
                      {dayComplete
                        ? <span className="badge badge-green" style={{ fontSize:10 }}>✓ Complète</span>
                        : <span className="text-dim" style={{ fontSize:11 }}>{dayPlayed}/9</span>}
                      {!dayComplete && (
                        <button className="btn btn-xs btn-sim" style={{ marginLeft:4 }}
                          style={{ display: isPublicMode ? 'none' : undefined }} onClick={e => { e.stopPropagation(); if(!isPublicMode){ const sy = window.scrollY; simulateDay(leagueTab, activeGroup); setOpenDay(day); requestAnimationFrame(() => requestAnimationFrame(() => window.scrollTo(0, sy))); } }}>
                          🎲
                        </button>
                      )}
                      <span style={{ color:'var(--text-dim)',fontSize:11,marginLeft:4 }}>{isOpen ? '▲' : '▼'}</span>
                    </div>

                    {/* Match list for this day */}
                    {isOpen && (
                      <div style={{ border:'1px solid var(--gold-dim)',borderTop:'none',borderRadius:'0 0 3px 3px',background:'var(--dark2)',padding:'4px 6px' }}>
                        {dayMatches.map(m => {
                          const home = groupCars.find(c => c.id === m.homeId);
                          const away = groupCars.find(c => c.id === m.awayId);
                          const isPlayed = m.homeGoals !== null;
                          const hWin = isPlayed && m.homeGoals > m.awayGoals;
                          const aWin = isPlayed && m.awayGoals > m.homeGoals;
                          const homePhoto = getCarPhoto(m.homeId);
                          const awayPhoto = getCarPhoto(m.awayId);
                          const homeStats = getCarStats(m.homeId, matches);
                          const awayStats = getCarStats(m.awayId, matches);
                          const quals = computeQualifications(leagueTab);
                          function getQualBadge(id) {
                            return quals.Z.has(id) ? { label:'Z', bg:'#c9a84c', color:'#000' }
                                 : quals.Y.has(id) ? { label:'Y', bg:'#27ae60', color:'#fff' }
                                 : quals.X.has(id) ? { label:'X', bg:'#2980b9', color:'#fff' }
                                 : quals.P.has(id) ? { label:'P', bg:'#16a085', color:'#fff' }
                                 : quals.ELIM.has(id) ? { label:'!', bg:'#e74c3c', color:'#fff' }
                                 : null;
                          }
                          const homeRank = standings.findIndex(s => s.id === m.homeId) + 1;
                          const awayRank = standings.findIndex(s => s.id === m.awayId) + 1;
                          const homePts = standings.find(s => s.id === m.homeId)?.pts ?? 0;
                          const awayPts = standings.find(s => s.id === m.awayId)?.pts ?? 0;
                          return (
                            <div key={m.id}
                              onClick={() => openMatchModal({
                                homeName: home?.name, awayName: away?.name,
                                homePhoto, awayPhoto,
                                homeGoals: m.homeGoals, awayGoals: m.awayGoals,
                                homeStats, awayStats,
                                homeRank, awayRank, homePts, awayPts,
                                homeQual: getQualBadge(m.homeId),
                                awayQual: getQualBadge(m.awayId),
                                onConfirm: (hg, ag) => updateGroupMatch(leagueTab, activeGroup, m.id, hg, ag),
                              })}
                              style={{
                                display:'flex',alignItems:'center',gap:8,padding:'8px 10px',borderBottom:'1px solid #1a1a1a',cursor:'pointer',borderLeft:isPlayed ? '3px solid var(--green)' :'3px solid transparent',background:isPlayed ? 'rgba(39,174,96,0.03)' :'transparent',borderRadius:3,transition:'background 0.1s',}}>
                              {/* Home */}
                              <div style={{ flex:1,display:'flex',alignItems:'center',gap:6,justifyContent:'flex-end' }}>
                                <div style={{ fontSize:12,fontWeight:600,textAlign:'right',color:hWin ? 'var(--green)' :aWin ? 'var(--text-dim)' :'var(--text)',lineHeight:1.2 }}>{home?.name}</div>
                                <CarThumb photo={homePhoto} size={40} />
                              </div>
                              {/* Score */}
                              <div style={{ fontFamily:"'Bebas Neue',sans-serif",fontSize:20,flexShrink:0,minWidth:52,textAlign:'center',letterSpacing:2,display:'flex',alignItems:'center',justifyContent:'center',gap:2 }}>
                                {isPlayed ? (
                                  <>
                                    <span style={{ color:hWin ? 'var(--green)' :aWin ? '#e74c3c' :'var(--gold)' }}>{m.homeGoals}</span>
                                    <span style={{ color:'var(--text-dim)' }}> : </span>
                                    <span style={{ color:aWin ? 'var(--green)' :hWin ? '#e74c3c' :'var(--gold)' }}>{m.awayGoals}</span>
                                  </>
                                ) : <span style={{ color:'var(--text-dim)' }}>— : —</span>}
                              </div>
                              {/* Away */}
                              <div style={{ flex:1,display:'flex',alignItems:'center',gap:6 }}>
                                <CarThumb photo={awayPhoto} size={40} />
                                <div style={{ fontSize:12,fontWeight:600,color:aWin ? 'var(--green)' :hWin ? 'var(--text-dim)' :'var(--text)',lineHeight:1.2 }}>{away?.name}</div>
                              </div>
                            </div>
                          );
                        })}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      </div>
    );
  }

  const [showBracket, setShowBracket] = useState(false);

  function PlayoffsView() {
    const league = getLeague(leagueTab);
    const pm = league.playoffResults || {};
    const allMatches = Object.values(pm);
    const r1 = allMatches.filter(m => m.round === 'r1').sort((a,b) => a.bracketPos - b.bracketPos);
    const r2 = allMatches.filter(m => m.round === 'r2').sort((a,b) => a.bracketPos - b.bracketPos);
    const r3 = allMatches.filter(m => m.round === 'r3').sort((a,b) => a.bracketPos - b.bracketPos);
    const qf = allMatches.filter(m => m.round === 'qf').sort((a,b) => a.bracketPos - b.bracketPos);
    const sf = allMatches.filter(m => m.round === 'sf').sort((a,b) => a.bracketPos - b.bracketPos);
    const fin = allMatches.find(m => m.round === 'final');
    // showBracket lives in App state to persist across re-renders

    const ROUND_LABELS = { r1: 'Ronde 1', r2: 'Ronde 2', r3: 'Ronde 3', qf: 'Quarts de Finale', sf: 'Demi-Finales', final: 'Finale' };

    // Bracket visual component — symétrique gauche/droite
    function BracketView() {
      // R1: pos 1-16 = left half, pos 17-32 = right half
      const leftR1  = r1.filter(m => m.bracketPos <= 16).sort((a,b) => a.bracketPos - b.bracketPos);
      const rightR1 = r1.filter(m => m.bracketPos > 16).sort((a,b) => a.bracketPos - b.bracketPos);
      const leftR2  = r2.slice(0, 8);
      const rightR2 = r2.slice(8, 16);
      const leftR3  = r3.slice(0, 4);
      const rightR3 = r3.slice(4, 8);
      const leftQF  = qf.slice(0, 2);
      const rightQF = qf.slice(2, 4);
      const leftSF  = sf[0] ? [sf[0]] : [];
      const rightSF = sf[1] ? [sf[1]] : [];

      // Card dimensions
      const CARD_W = 110;
      const CARD_H = 108;
      const MATCH_GAP = 3;
      const MATCH_H = CARD_H * 2 + MATCH_GAP;
      const COL_GAP = 24;

      function getWinnerId(m) {
        if (!m || m.homeGoals === null) return null;
        return m.homeGoals > m.awayGoals ? m.homeId : m.awayId;
      }

      function CarCard({ carId, isWinner, goals }) {
        const IMG_H = 55;
        if (!carId) return (
          <div style={{ width:CARD_W, height:CARD_H, background:'var(--dark3)', border:'1px solid var(--border)', borderRadius:6, display:'flex', alignItems:'center', justifyContent:'center', opacity:0.3 }}>
            <span style={{ fontSize:9, color:'var(--text-dim)' }}>En attente</span>
          </div>
        );
        const car = getCar(leagueTab, carId);
        const name = car?.name || '?';
        const photo = getCarPhoto(carId);
        const stats = getCarStats(carId, Object.values(league.groupResults || {}).flat());
        const carObj = league.cars?.find(c => c.id === carId);
        const groupCars = carObj ? (league.cars || []).filter(c => c.group === carObj.group) : [];
        const groupMatches = (league.groupResults?.[carObj?.group] || []);
        const groupStandings = computeStandings(groupCars, groupMatches);
        const groupRank = groupStandings.findIndex(s => s.id === carId) + 1;
        const groupPts = groupStandings.find(s => s.id === carId)?.pts ?? 0;
        return (
          <div style={{ width:CARD_W, height:CARD_H, background: isWinner ? 'rgba(201,168,76,0.18)' : 'var(--dark3)', border:`2px solid ${isWinner ? 'var(--gold)' : 'var(--border)'}`, borderRadius:6, overflow:'hidden', cursor:'pointer', flexShrink:0 }}
            onClick={e => { e.stopPropagation(); openProfileCar({ leagueName: leagueTab, carId }); }}>
            <div style={{ width:'100%', height:IMG_H, background:'var(--dark2)', overflow:'hidden', display:'flex', alignItems:'center', justifyContent:'center' }}>
              {photo
                ? <img src={photo} alt="" style={{ width:'100%', height:'100%', objectFit:'cover', objectPosition:'center' }} />
                : <span style={{ fontSize:22 }}>🚗</span>}
            </div>
            <div style={{ padding:'2px 5px' }}>
              <div style={{ display:'flex', alignItems:'center', gap:3 }}>
                <span style={{ fontSize:9, fontWeight:700, color: isWinner ? 'var(--gold)' : 'var(--text)', flex:1, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>{name}</span>
                {goals !== null && goals !== undefined && (
                  <span style={{ fontFamily:"'Bebas Neue',sans-serif", fontSize:15, color: isWinner ? 'var(--green)' : 'var(--text-dim)', flexShrink:0 }}>{goals}</span>
                )}
              </div>
              <div style={{ display:'flex', gap:3, marginTop:1, flexWrap:'wrap' }}>
                {groupRank > 0 && <span style={{ fontSize:8, color:'var(--gold-dim)' }}>#{groupRank} G{(carObj?.group ?? 0)+1}</span>}
                {groupPts > 0 && <span style={{ fontSize:8, color:'var(--gold)' }}>{groupPts}pts</span>}
                <span style={{ fontSize:8, color:'var(--green)' }}>{stats.w}V</span>
                <span style={{ fontSize:8, color:'var(--text-dim)' }}>{stats.d}N</span>
                <span style={{ fontSize:8, color:'#e74c3c' }}>{stats.l}D</span>
              </div>
            </div>
          </div>
        );
      }

      function MatchBlock({ m, onConfirm, mirror, rIdx, i, betweenGap, isLast }) {
        if (!m) return null;
        const winnerId = getWinnerId(m);
        const lineColor = "rgba(201,168,76,0.35)";

        return (
          <div style={{ position:'relative', marginTop: i === 0 ? betweenGap/2 : 0 }}>
            <div style={{ cursor:'pointer', display:'flex', flexDirection:'column', gap:MATCH_GAP }}
              onClick={() => openMatchModal({
                homeName: getCar(leagueTab, m?.homeId)?.name,
                awayName: getCar(leagueTab, m?.awayId)?.name,
                homePhoto: getCarPhoto(m?.homeId),
                awayPhoto: getCarPhoto(m?.awayId),
                homeGoals: m?.homeGoals, awayGoals: m?.awayGoals,
                onConfirm,
              })}>
              <CarCard carId={m?.homeId} isWinner={winnerId === m?.homeId} goals={m?.homeGoals} />
              <CarCard carId={m?.awayId} isWinner={winnerId === m?.awayId} goals={m?.awayGoals} />
            </div>
            {!isLast && (
              <svg style={{ position:'absolute', [mirror ? 'right' : 'left']: CARD_W, top:0, overflow:'visible', pointerEvents:'none' }} width={COL_GAP} height={MATCH_H}>
                <line x1={mirror ? COL_GAP : 0} y1={MATCH_H/2} x2={COL_GAP/2} y2={MATCH_H/2} stroke={lineColor} strokeWidth="1.5" />
                {i % 2 === 0
                  ? <line x1={COL_GAP/2} y1={MATCH_H/2} x2={COL_GAP/2} y2={MATCH_H + betweenGap + MATCH_H/2} stroke={lineColor} strokeWidth="1.5" />
                  : <line x1={COL_GAP/2} y1={MATCH_H/2} x2={COL_GAP/2} y2={-(betweenGap + MATCH_H/2)} stroke={lineColor} strokeWidth="1.5" />
                }
                <line x1={COL_GAP/2} y1={MATCH_H/2} x2={mirror ? 0 : COL_GAP} y2={MATCH_H/2} stroke={lineColor} strokeWidth="1.5" />
              </svg>
            )}
          </div>
        );
      }

      function HalfBracket({ roundSets, labels, mirror }) {
        // mirror=false: R1 on left, SF on right (→ toward center)
        // mirror=true:  SF on left, R1 on right (← toward center)
        const cols = mirror ? [...roundSets].reverse() : roundSets;
        const colLabels = mirror ? [...labels].reverse() : labels;

        return (
          <div style={{ display:'flex', flexDirection:'row', gap:0 }}>
            {cols.map((roundMatches, colIdx) => {
              const rIdx = mirror ? roundSets.length - 1 - colIdx : colIdx;
              const spacing = Math.pow(2, rIdx);
              const betweenGap = (MATCH_H + MATCH_GAP) * spacing - MATCH_H;
              const isLast = mirror ? colIdx === 0 : colIdx === cols.length - 1;

              return (
                <div key={colIdx} style={{ display:'flex', flexDirection:'column', alignItems:'center', marginRight: !mirror && !isLast ? COL_GAP : 0, marginLeft: mirror && !isLast ? COL_GAP : 0 }}>
                  <div style={{ fontFamily:"'Bebas Neue',sans-serif", fontSize:9, color:'var(--gold-dim)', letterSpacing:1, marginBottom:6, textAlign:'center', width:CARD_W }}>
                    {colLabels[colIdx]}
                  </div>
                  <div style={{ display:'flex', flexDirection:'column', gap:betweenGap }}>
                    {roundMatches.map((m, i) => (
                      <MatchBlock key={m?.id || i} m={m} mirror={mirror} rIdx={rIdx} i={i} betweenGap={betweenGap} isLast={isLast}
                        onConfirm={(hg, ag) => updatePlayoffMatch(leagueTab, m.id, hg, ag)} />
                    ))}
                  </div>
                </div>
              );
            })}
          </div>
        );
      }

      const leftRounds = [leftR1, leftR2, leftR3, leftQF, leftSF];
      const rightRounds = [rightR1, rightR2, rightR3, rightQF, rightSF];
      const roundLabels = ['R1', 'R2', 'R3', 'QF', 'SF'];

      return (
        <div style={{ overflowX:'auto', WebkitOverflowScrolling:'touch', background:'var(--dark2)', borderRadius:8, padding:12 }}>
          <div style={{ display:'flex', alignItems:'center', gap:0 }}>
            {/* Left: R1→SF (left to right) */}
            <HalfBracket roundSets={leftRounds} labels={roundLabels} mirror={false} />

            {/* Center: Finale */}
            <div style={{ display:'flex', flexDirection:'column', alignItems:'center', margin:`0 ${COL_GAP}px`, flexShrink:0 }}>
              <div style={{ fontFamily:"'Bebas Neue',sans-serif", fontSize:11, color:'var(--gold)', letterSpacing:2, marginBottom:6, textAlign:'center' }}>🏆 FINALE</div>
              {fin ? (
                <div style={{ cursor:'pointer', display:'flex', flexDirection:'column', gap:MATCH_GAP }}
                  onClick={() => openMatchModal({
                    homeName: getCar(leagueTab, fin.homeId)?.name,
                    awayName: getCar(leagueTab, fin.awayId)?.name,
                    homePhoto: getCarPhoto(fin.homeId),
                    awayPhoto: getCarPhoto(fin.awayId),
                    homeGoals: fin.homeGoals, awayGoals: fin.awayGoals,
                    onConfirm: (hg, ag) => updatePlayoffMatch(leagueTab, fin.id, hg, ag),
                  })}>
                  <CarCard carId={fin.homeId} isWinner={getWinnerId(fin) === fin.homeId} goals={fin.homeGoals} />
                  <CarCard carId={fin.awayId} isWinner={getWinnerId(fin) === fin.awayId} goals={fin.awayGoals} />
                </div>
              ) : (
                <div style={{ width:CARD_W, height:MATCH_H, background:'var(--dark3)', border:'1px solid var(--gold-dim)', borderRadius:8, display:'flex', alignItems:'center', justifyContent:'center', opacity:0.4 }}>
                  <span style={{ fontSize:10, color:'var(--gold-dim)' }}>En attente</span>
                </div>
              )}
            </div>

            {/* Right: SF→R1 (mirrored, right to left) */}
            <HalfBracket roundSets={rightRounds} labels={roundLabels} mirror={true} />
          </div>
        </div>
      );
    }

      // Card dimensions
      const CARD_W = 110;
      const CARD_H = 105; // taller to fit stats
      const MATCH_GAP = 3;
      const MATCH_H = CARD_H * 2 + MATCH_GAP;
      const COL_GAP = 28;

      function getWinnerId(m) {
        if (!m || m.homeGoals === null) return null;
        return m.homeGoals > m.awayGoals ? m.homeId : m.awayId;
      }


    function simPO(matchId) {
      let h, a;
      do { const r = simScore(); h = r.h; a = r.a; } while (h === a);
      updatePlayoffMatch(leagueTab, matchId, h, a);
    }

    function simRound(round) {
      const roundMatches = allMatches.filter(m => m.round === round && m.homeId !== null);
      updateLeague(leagueTab, l => {
        const pm = { ...l.playoffResults };
        roundMatches.forEach(m => {
          if (pm[m.id].homeGoals !== null) return;
          let h, a;
          do { const r = simScore(); h = r.h; a = r.a; } while (h === a);
          pm[m.id] = { ...pm[m.id], homeGoals: h, awayGoals: a };
        });
        return { ...l, playoffResults: pm };
      });
      setTimeout(() => advancePlayoffBracket(leagueTab), 80);
    }

    function POMatchCard({ m, compact }) {
      if (!m || !m.homeId) {
        return (
          <div style={{ background:'var(--dark3)',border:'1px solid var(--border)',borderRadius:4,padding:compact ? '6px 8px' :'8px 10px',opacity:0.4,marginBottom:4 }}>
            <div style={{ fontSize:11,color:'var(--text-dim)',textAlign:'center' }}>En attente...</div>
          </div>
        );
      }
      const home = getCar(leagueTab, m.homeId);
      const away = getCar(leagueTab, m.awayId);
      const homePhoto = getCarPhoto(m.homeId);
      const awayPhoto = getCarPhoto(m.awayId);
      const isPlayed = m.homeGoals !== null;
      const hWin = isPlayed && m.homeGoals > m.awayGoals;
      const aWin = isPlayed && m.awayGoals > m.homeGoals;

      function TeamRow({ carId, photo, car, seed, groupRank, fromGroup, goals, isWinner }) {
        const stats = carId ? getCarStats(carId, Object.values(currentSeason.leagues[leagueTab]?.groupResults || {}).flat()) : null;
        const carObj = currentSeason.leagues[leagueTab]?.cars?.find(c => c.id === carId);
        const groupCars = carObj ? (currentSeason.leagues[leagueTab]?.cars || []).filter(c => c.group === carObj.group) : [];
        const groupMatches = currentSeason.leagues[leagueTab]?.groupResults?.[carObj?.group] || [];
        const groupStandings = computeStandings(groupCars, groupMatches);
        const groupPts = groupStandings.find(s => s.id === carId)?.pts ?? 0;
        return (
          <div style={{
            display:'flex',alignItems:'center',gap:compact ? 6 :10,padding:compact ? '8px 10px' :'12px 14px',borderBottom:'1px solid #1a1a1a',background:isWinner ? 'rgba(201,168,76,0.12)' :'transparent',}}>
            {/* Seed badge */}
            <div style={{ fontFamily:"'Bebas Neue',sans-serif",fontSize:compact ? 15 :18,color:'var(--gold-dim)',width:compact ? 30 :36,textAlign:'center',flexShrink:0 }}>
              #{seed}
            </div>
            {/* Photo */}
            <CarThumb photo={photo} size={compact ? 52 : 64} />
            {/* Name + stats */}
            <div style={{ flex:1,minWidth:0 }}>
              <div style={{ fontSize:compact ? 17 :20,fontWeight:700,color:isWinner ? 'var(--gold)' :'var(--text)',whiteSpace:'nowrap',overflow:'hidden',textOverflow:'ellipsis' }}>
                {car?.name || '?'}
              </div>
              <div style={{ display:'flex',gap:6,alignItems:'center',flexWrap:'wrap',marginTop:2 }}>
                <span style={{ fontSize:11,color:'var(--text-dim)' }}>G{fromGroup + 1} · {groupRank}e</span>
                {groupPts > 0 && <span style={{ fontSize:11,color:'var(--gold)',fontFamily:"'Bebas Neue',sans-serif" }}>{groupPts}pts</span>}
                {stats && <>
                  <span style={{ fontSize:11,color:'var(--green)' }}>{stats.w}V</span>
                  <span style={{ fontSize:11,color:'var(--text-dim)' }}>{stats.d}N</span>
                  <span style={{ fontSize:11,color:'#e74c3c' }}>{stats.l}D</span>
                </>}
              </div>
            </div>
            {/* Score */}
            {isPlayed && (
              <div style={{ fontFamily:"'Bebas Neue',sans-serif",fontSize:compact ? 26 :34,color:isWinner ? 'var(--green)' :'var(--text-dim)',flexShrink:0 }}>
                {goals}
              </div>
            )}
            {isWinner && <span style={{ fontSize:12,flexShrink:0 }}>🏆</span>}
          </div>
        );
      }

      const poMatches = Object.values(currentSeason.leagues[leagueTab]?.playoffResults || {});
      const homeStats = getGroupStatsForCar(m.homeId, leagueTab);
      const awayStats = getGroupStatsForCar(m.awayId, leagueTab);
      return (
        <div style={{ background:'var(--dark3)',border:`1px solid ${isPlayed ? 'var(--gold-dim)' :'var(--border)'}`,borderRadius:4,overflow:'hidden',marginBottom:6,cursor:'pointer' }}
          onClick={() => openMatchModal({
            homeName: home?.name, awayName: away?.name,
            homePhoto, awayPhoto,
            homeGoals: m.homeGoals, awayGoals: m.awayGoals,
            homeStats, awayStats,
            onConfirm: (hg, ag) => updatePlayoffMatch(leagueTab, m.id, hg, ag),
          })}>
          <TeamRow carId={m.homeId} photo={homePhoto} car={home} seed={m.homeSeed} groupRank={m.homeGroupRank} fromGroup={m.homeGroup} goals={m.homeGoals} isWinner={hWin} />
          <TeamRow carId={m.awayId} photo={awayPhoto} car={away} seed={m.awaySeed} groupRank={m.awayGroupRank} fromGroup={m.awayGroup} goals={m.awayGoals} isWinner={aWin} />
        </div>
      );
    }

    function RoundSection({ label, matches, round }) {
      const played = matches.filter(m => m.homeGoals !== null).length;
      const available = matches.filter(m => m.homeId !== null).length;
      return (
        <div className="card mb-16">
          <div className="card-header">
            <div className="card-title">{label}</div>
            <div style={{ flex:1 }} />
            <span className="text-dim" style={{ fontSize:12 }}>{played}/{available} joués</span>
            <button className="btn btn-sm btn-sim" style={{ marginLeft:10 }} style={{ display: isPublicMode ? 'none' : undefined }} onClick={() => { if(!isPublicMode) simRound(round); }}>
              ⚡ Simuler {label}
            </button>
          </div>
          <div className="card-body" style={{ maxHeight:round === 'r1' ? 520 :420,overflowY:'auto' }}>
            <div style={{ display:'grid',gridTemplateColumns:`repeat(auto-fill,minmax(${round === 'r1' ? 240 :round === 'r2' ? 260 :280}px,1fr))`,gap:12 }}>
              {matches.map(m => <POMatchCard key={m.id} m={m} compact={round === 'r1'} />)}
            </div>
          </div>
        </div>
      );
    }

    return (
      <div>
        {r1.length === 0 ? (
          <div className="card" style={{ padding:32,textAlign:'center' }}>
            <div className="text-dim" style={{ marginBottom:8 }}>
              64 voitures qualifiées (Top 8 par groupe) seedées globalement par points
            </div>
            <div className="text-dim" style={{ fontSize:12,marginBottom:20 }}>
              Bracket fixe : Seed 1 vs 64 · Seed 2 vs 63 · ... · 6 rondes jusqu'au champion
            </div>
            {(() => {
              const league = currentSeason.leagues[leagueTab];
              const allGroupsDone = Array.from({ length: GROUPS }, (_, g) => {
                const gc = (league?.cars || []).filter(c => c.group === g);
                const matches = league?.groupResults?.[g] || [];
                const expected = gc.length * (gc.length - 1) / 2;
                const played = matches.filter(m => m.homeGoals !== null).length;
                return played >= expected && expected > 0;
              }).every(Boolean);
              return allGroupsDone
                ? (!isPublicMode && <button className="btn btn-gold" onClick={() => initPlayoffs(leagueTab)}>Générer le Bracket (64 voitures)</button>)
                : <div style={{ color:'var(--red)',fontSize:13,marginTop:8 }}>⛔ Tous les matchs de groupes doivent être joués avant de générer les playoffs.</div>;
            })()}
          </div>
        ) : (
          <div>
            <div className="sim-bar" style={{ marginBottom:12 }}>
              <span className="text-dim font-bebas" style={{ fontSize:13,marginRight:4 }}>Simulation:</span>
              <button className="btn btn-sm" style={{ background:'rgba(155,89,182,0.15)',border:'1px solid rgba(155,89,182,0.4)',color:'#a569bd' }}
                style={{ display: isPublicMode ? 'none' : undefined }} onClick={() => { if(!isPublicMode) simulatePlayoffsComplete(leagueTab); }}>
                ⚡⚡ Tous les playoffs
              </button>
            </div>
            {/* Toggle bracket */}
            <div style={{ marginBottom:12 }}>
              <button className="btn btn-sm" style={{ background: showBracket ? 'rgba(201,168,76,0.2)' : 'var(--dark3)', borderColor: showBracket ? 'var(--gold)' : 'var(--border)', color: showBracket ? 'var(--gold)' : 'var(--text-dim)' }}
                onClick={() => setShowBracket(b => !b)}>
                🏆 {showBracket ? 'Masquer' : 'Voir'} le Bracket
              </button>
            </div>
            {showBracket && (
              <div className="card" style={{ marginBottom:12 }}>
                <div className="card-header"><div className="card-title">🏆 Bracket — {leagueTab}</div></div>
                <div className="card-body" style={{ padding:8 }}>
                  <BracketView />
                </div>
              </div>
            )}
            <RoundSection label="Ronde 1 (64→32)" matches={r1} round="r1" />
            <RoundSection label="Ronde 2 (32→16)" matches={r2} round="r2" />
            <RoundSection label="Ronde 3 (16→8)" matches={r3} round="r3" />
            <RoundSection label="Quarts de Finale (8→4)" matches={qf} round="qf" />
            <RoundSection label="Demi-Finales (4→2)" matches={sf} round="sf" />
            {fin && (
              <div className="card mb-16">
                <div className="card-header">
                  <div className="card-title">🏆 Finale</div>
                  <div style={{ flex:1 }} />
                  <button className="btn btn-sm btn-sim" style={{ display: isPublicMode ? 'none' : undefined }} onClick={() => { if(!isPublicMode) simRound('final'); }}>🎲 Simuler</button>
                </div>
                <div className="card-body" style={{ maxWidth:320 }}>
                  <POMatchCard m={fin} compact={false} />
                  {fin.homeGoals !== null && (
                    <button className="btn btn-gold" style={{ marginTop:10,width:'100%' }} onClick={() => finalizeChampion(leagueTab)}>
                      ✓ Enregistrer le Champion
                    </button>
                  )}
                </div>
              </div>
            )}
          </div>
        )}
      </div>
    );
  }

  function RelegationView() {
    const league = getLeague(leagueTab);
    const rm = league.relegationResults || {};
    const relCars = (league.relegationCars || []).map(id => getCar(leagueTab, id)).filter(Boolean);
    const relMatches = Object.values(rm);
    const standings = relMatches.length > 0 ? computeStandings(relCars, relMatches) : [];
    const relId = currentSeason.relegated[leagueTab];
    const [openDay, setOpenDay] = useState(1);

    const days = [...new Set(relMatches.map(m => m.day))].sort((a,b) => a - b);
    const nextUnplayedDay = days.find(d => relMatches.filter(m => m.day === d).some(m => m.homeGoals === null));
    const playedCount = relMatches.filter(m => m.homeGoals !== null).length;

    function simulateRelDay() {
      if (nextUnplayedDay === undefined) return;
      updateLeague(leagueTab, l => {
        const updated = { ...l.relegationResults };
        Object.values(updated).forEach(m => {
          if (m.day !== nextUnplayedDay || m.homeGoals !== null) return;
          const s = simScore();
          updated[m.id] = { ...m, homeGoals: s.h, awayGoals: s.a };
        });
        return { ...l, relegationResults: updated };
      });
    }

    function simulateRelAll() {
      updateLeague(leagueTab, l => {
        const updated = { ...l.relegationResults };
        Object.values(updated).forEach(m => {
          if (m.homeGoals !== null) return;
          const s = simScore();
          updated[m.id] = { ...m, homeGoals: s.h, awayGoals: s.a };
        });
        return { ...l, relegationResults: updated };
      });
    }

    function simulateRelMatch(matchId) {
      const s = simScore();
      updateRelegationMatch(leagueTab, matchId, s.h, s.a);
    }

    return (
      <div>
        {relCars.length === 0 ? (
          <div className="card" style={{ padding:32,textAlign:'center' }}>
            <div className="text-dim" style={{ marginBottom:8 }}>
              Barrage de relégation : les 8 derniers (un par groupe) s'affrontent en round-robin
            </div>
            <div className="text-dim" style={{ fontSize:12,marginBottom:20 }}>7 journées de 4 matchs · Le dernier est relégué</div>
            {(() => {
              const league = currentSeason.leagues[leagueTab];
              const allGroupsDone = Array.from({ length: GROUPS }, (_, g) => {
                const gc = (league?.cars || []).filter(c => c.group === g);
                const matches = league?.groupResults?.[g] || [];
                const expected = gc.length * (gc.length - 1) / 2;
                const played = matches.filter(m => m.homeGoals !== null).length;
                return played >= expected && expected > 0;
              }).every(Boolean);
              return allGroupsDone
                ? (!isPublicMode && <button className="btn btn-gold" onClick={() => initRelegation(leagueTab)}>Générer le Barrage Relégation</button>)
                : <div style={{ color:'var(--red)',fontSize:13,marginTop:8 }}>⛔ Tous les matchs de groupes doivent être joués avant de générer le barrage.</div>;
            })()}
          </div>
        ) : (
          <div>
            <div className="sim-bar" style={{ marginBottom:12 }}>
              <span className="text-dim font-bebas" style={{ fontSize:13,marginRight:4 }}>Simulation:</span>
              <button className="btn btn-sm btn-sim" style={{ display: isPublicMode ? 'none' : undefined }} onClick={() => { if(!isPublicMode) simulateRelDay(); }}>▶ Journée {(nextUnplayedDay ?? '—')}</button>
              <button className="btn btn-sm btn-sim-all" style={{ display: isPublicMode ? 'none' : undefined }} onClick={() => { if(!isPublicMode) simulateRelAll(); }}>⚡ Barrage complet</button>
              <button className="btn btn-sm" style={{ background:'rgba(155,89,182,0.15)',border:'1px solid rgba(155,89,182,0.4)',color:'#a569bd' }}
                style={{ display: isPublicMode ? 'none' : undefined }} onClick={() => { if(!isPublicMode) simulateRelegationComplete(leagueTab); }}>
                ⚡⚡ Tout simuler + confirmer
              </button>
            </div>
          <div className="grid-2">
            {/* Classement */}
            <div className="card">
              <div className="card-header">
                <div className="card-title">Classement Barrage</div>
                {relId && <span className="badge badge-red" style={{ marginLeft:8 }}>⬇ {getCar(leagueTab, relId)?.name}</span>}
              </div>
              <div className="card-body" style={{ padding:0 }}>
                <div>
                    {standings.map((s, i) => {
                      const photo = getCarPhoto(s.id);
                      const isLast = i === standings.length - 1;
                      const badge = isLast ? { label:'⬇ RELÉGUÉ', bg:'rgba(192,57,43,0.25)', color:'#e74c3c' } : null;
                      return (
                        <LeaderboardRow key={s.id}
                          rank={i+1} rankDiff={null}
                          carId={s.id} leagueName={leagueTab}
                          name={s.name} photo={photo} badge={badge}
                          pts={s.pts} w={s.w} d={s.d} l={s.l}
                          gf={s.gf} ga={s.ga} gp={s.gp}
                          borderColor={isLast ? '#e74c3c' : 'transparent'}
                          onClick={() => openProfileCar({ leagueName: leagueTab, carId: s.id })}
                        />
                      );
                    })}
                </div>
                {standings.length > 0 && !relId && (
                  <div style={{ padding:12 }}>
                    <button className="btn btn-danger btn-sm" onClick={() => finalizeRelegation(leagueTab)}>
                      ✓ Confirmer la Relégation
                    </button>
                  </div>
                )}
              </div>
            </div>

            {/* Matchs par journée */}
            <div className="card">
              <div className="card-header">
                <div className="card-title">Matchs du Barrage</div>
                <div style={{ flex:1 }} />
                <span className="text-dim" style={{ fontSize:12 }}>{playedCount}/{relMatches.length}</span>
              </div>
              <div className="card-body" style={{ padding:'6px' }}>
                {/* Sim bar */}
                <div className="sim-bar" style={{ marginBottom:8 }}>
                  <button className="btn btn-sm btn-sim"
                    style={{ opacity:nextUnplayedDay === undefined ? 0.4 :1 }}
                    style={{ display: isPublicMode ? 'none' : undefined }} onClick={() => { if(!isPublicMode){ simulateRelDay(); setOpenDay(nextUnplayedDay); } }}>
                    ▶ Journée {(nextUnplayedDay ?? '—')}
                  </button>
                  <button className="btn btn-sm btn-sim-all" style={{ display: isPublicMode ? 'none' : undefined }} onClick={() => { if(!isPublicMode) simulateRelAll(); }}>⚡ Tout simuler</button>
                </div>

                <div style={{ maxHeight:480,overflowY:'auto' }}>
                  {days.map(day => {
                    const dayMatches = relMatches.filter(m => m.day === day);
                    const dayPlayed = dayMatches.filter(m => m.homeGoals !== null).length;
                    const dayComplete = dayPlayed === dayMatches.length;
                    const isOpen = openDay === day;
                    return (
                      <div key={day} style={{ marginBottom:3 }}>
                        <div onClick={() => {
  const scrollY = window.scrollY;
  document.body.style.position = 'fixed';
  document.body.style.top = `-${scrollY}px`;
  document.body.style.width = '100%';
  setOpenDay(isOpen ? null : day);
  requestAnimationFrame(() => {
    document.body.style.position = '';
    document.body.style.top = '';
    document.body.style.width = '';
    window.scrollTo(0, scrollY);
  });
}}
                          style={{
                            display:'flex',alignItems:'center',gap:8,padding:'7px 10px',cursor:'pointer',borderRadius:isOpen ? '3px 3px 0 0' :3,background:isOpen ? 'rgba(201,168,76,0.1)' :'var(--dark3)',border:`1px solid ${isOpen ? 'var(--gold-dim)' :'var(--border)'}`,userSelect:'none'
                          }}>
                          <span style={{ fontFamily:"'Bebas Neue',sans-serif",letterSpacing:2,fontSize:14,color:isOpen ? 'var(--gold)' :'var(--text-dim)' }}>
                            Journée {day}
                          </span>
                          <span style={{ flex:1 }} />
                          {dayComplete
                            ? <span className="badge badge-green" style={{ fontSize:10 }}>✓</span>
                            : <span className="text-dim" style={{ fontSize:11 }}>{dayPlayed}/4</span>}
                          {!dayComplete && (
                            <button className="btn btn-xs btn-sim" style={{ marginLeft:4 }}
                              style={{ display: isPublicMode ? 'none' : undefined }} onClick={e => { e.stopPropagation(); if(!isPublicMode){ simulateRelDay(); setOpenDay(day); } }}>🎲</button>
                          )}
                          <span style={{ color:'var(--text-dim)',fontSize:11,marginLeft:4 }}>{isOpen ? '▲' : '▼'}</span>
                        </div>
                        {isOpen && (
                          <div style={{ border:'1px solid var(--gold-dim)',borderTop:'none',borderRadius:'0 0 3px 3px',background:'var(--dark2)',padding:'4px 6px' }}>
                            {dayMatches.map(m => {
                              const home = relCars.find(c => c.id === m.homeId);
                              const away = relCars.find(c => c.id === m.awayId);
                              const homePhoto = getCarPhoto(m.homeId);
                              const awayPhoto = getCarPhoto(m.awayId);
                              const isPlayed = m.homeGoals !== null;
                              const hWin = isPlayed && m.homeGoals > m.awayGoals;
                              const aWin = isPlayed && m.awayGoals > m.homeGoals;
                              const relMatches = Object.values(currentSeason.leagues[leagueTab]?.relegationResults || {});
                              const homeStats = getGroupStatsForCar(m.homeId, leagueTab);
                              const awayStats = getGroupStatsForCar(m.awayId, leagueTab);
                              return (
                                <div key={m.id}
                                  onClick={() => openMatchModal({
                                    homeName: home?.name, awayName: away?.name,
                                    homePhoto, awayPhoto,
                                    homeGoals: m.homeGoals, awayGoals: m.awayGoals,
                                    homeStats, awayStats,
                                    onConfirm: (hg, ag) => updateRelegationMatch(leagueTab, m.id, hg, ag),
                                  })}
                                  style={{
                                    display:'flex',alignItems:'center',gap:8,padding:'8px 10px',borderBottom:'1px solid #1a1a1a',cursor:'pointer',borderLeft:isPlayed ? '3px solid var(--green)' :'3px solid transparent',background:isPlayed ? 'rgba(39,174,96,0.03)' :'transparent',borderRadius:3,}}>
                                  <div style={{ flex:1,display:'flex',alignItems:'center',gap:6,justifyContent:'flex-end' }}>
                                    <div style={{ fontSize:12,fontWeight:600,textAlign:'right',color:hWin ? 'var(--green)' :aWin ? 'var(--text-dim)' :'var(--text)' }}>{home?.name}</div>
                                    <CarThumb photo={homePhoto} size={40} />
                                  </div>
                                  <div style={{ fontFamily:"'Bebas Neue',sans-serif",fontSize:20,flexShrink:0,minWidth:52,textAlign:'center',letterSpacing:2,display:'flex',alignItems:'center',justifyContent:'center',gap:2 }}>
                                    {isPlayed ? (<><span style={{ color:hWin ? 'var(--green)' :aWin ? '#e74c3c' :'var(--gold)' }}>{m.homeGoals}</span><span style={{ color:'var(--text-dim)' }}> : </span><span style={{ color:aWin ? 'var(--green)' :hWin ? '#e74c3c' :'var(--gold)' }}>{m.awayGoals}</span></>) : <span style={{ color:'var(--text-dim)' }}>— : —</span>}
                                  </div>
                                  <div style={{ flex:1,display:'flex',alignItems:'center',gap:6 }}>
                                    <CarThumb photo={awayPhoto} size={40} />
                                    <div style={{ fontSize:12,fontWeight:600,color:aWin ? 'var(--green)' :hWin ? 'var(--text-dim)' :'var(--text)' }}>{away?.name}</div>
                                  </div>
                                </div>
                              );
                            })}
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
              </div>
            </div>
          </div>
          </div>
        )}
      </div>
    );
  }

  function BonusLeagueTable({ l, ldata, recentNums, oldNums }) {
    const allNums = [...oldNums, ...recentNums];
    const scrollRef = React.useRef(null);
    React.useEffect(() => {
      if (scrollRef.current) scrollRef.current.scrollLeft = scrollRef.current.scrollWidth;
    }, []);
    return (
      <div style={{ marginBottom:10 }}>
        <div style={{ display:'flex',alignItems:'center',justifyContent:'space-between',marginBottom:4 }}>
          <div style={{ fontSize:11,color:'var(--gold)',fontFamily:"'Bebas Neue',sans-serif",letterSpacing:2 }}>{l}</div>
          <div style={{ fontFamily:"'Bebas Neue',sans-serif",fontSize:24,color:'var(--gold)',letterSpacing:2,lineHeight:1 }}>
            {ldata.total} <span style={{ fontSize:12,color:'var(--text-dim)',fontFamily:'inherit' }}>PTS</span>
          </div>
        </div>
        <div ref={scrollRef} style={{ overflowX:'auto',WebkitOverflowScrolling:'touch' }}>
          <table className="tbl">
            <thead>
              <tr>
                {allNums.map(n => (
                  <th key={n} style={{ textAlign:'center',minWidth:42,fontSize:11,color:'var(--text-dim)' }}>S{n}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              <tr>
                {allNums.map(n => {
                  const pts = ldata.seasonPts[n];
                  const isChamp = ldata.champions.includes(n);
                  const isRel = ldata.relegated.includes(n);
                  return (
                    <td key={n} style={{
                      textAlign:'center',fontSize:13,padding:'6px 6px',color:pts ? (isChamp ? 'var(--green)' :isRel ? '#e74c3c' :'var(--gold)') :'var(--text-dim)',background:isChamp ? 'rgba(39,174,96,0.12)' :isRel ? 'rgba(192,57,43,0.12)' :'transparent',fontWeight:(isChamp || isRel) ? 700 :400,}}>
                      {pts ? `${pts}${isChamp ? '🏆' : isRel ? '⬇' : ''}` : '—'}
                    </td>
                  );
                })}
              </tr>
            </tbody>
          </table>
        </div>
      </div>
    );
  }

  function CarProfileModal() {
    if (!profileCar) return null;
    const { leagueName, carId, histName } = profileCar;
    const car = getCar(leagueName, carId);
    
    const effectiveName = car?.name || histName;
    if (!effectiveName) {
      for (const s of db.seasons) {
        for (const l of LEAGUES) {
          const f = s.leagues[l]?.cars.find(c => c.id === carId);
          if (f) { openProfileCar({ leagueName: l, carId }); return null; }
        }
      }
      return null;
    }
    const photo = car ? getCarPhoto(carId) : getCarPhotoByName(effectiveName);

    let totalW = 0, totalD = 0, totalL = 0, totalGF = 0, totalGA = 0, totalGP = 0;
    let totalBonusPts = 0, champCount = 0, relCount = 0;
    db.seasons.forEach(s => {
      const l = s.leagues[leagueName];
      if (!l) return;
      const carInSeason = l.cars.find(c => c.id === carId);
      if (!carInSeason) return;
      Object.values(l.groupResults || {}).forEach(matches => {
        matches.forEach(m => {
          if (m.homeGoals === null) return;
          if (m.homeId === carId) { totalGP++; totalGF += m.homeGoals; totalGA += m.awayGoals; if (m.homeGoals > m.awayGoals) totalW++; else if (m.homeGoals < m.awayGoals) totalL++; else totalD++; }
          if (m.awayId === carId) { totalGP++; totalGF += m.awayGoals; totalGA += m.homeGoals; if (m.awayGoals > m.homeGoals) totalW++; else if (m.awayGoals < m.homeGoals) totalL++; else totalD++; }
        });
      });
      (l.matches || []).forEach(m => {
        if (m.homeGoals === null) return;
        if (m.homeId === carId) { totalGP++; totalGF += m.homeGoals; totalGA += m.awayGoals; if (m.homeGoals > m.awayGoals) totalW++; else if (m.homeGoals < m.awayGoals) totalL++; else totalD++; }
        if (m.awayId === carId) { totalGP++; totalGF += m.awayGoals; totalGA += m.homeGoals; if (m.awayGoals > m.homeGoals) totalW++; else if (m.awayGoals < m.homeGoals) totalL++; else totalD++; }
      });
      if (s.champions[leagueName] === carId) champCount++;
      if (s.relegated[leagueName] === carId) relCount++;
      const bp = computeBonusPoints(s, leagueName);
      totalBonusPts += bp[carId] || 0;
    });
    const winPct = totalGP > 0 ? Math.round(totalW / totalGP * 100) : 0;
    const diff = totalGF - totalGA;

    const histByLeague = {};
    let histTotalPts = 0;
    const nameMap = db.nameMap?.[leagueName] || {};
    const histLookupName = nameMap[carId] || effectiveName;
    LEAGUES.forEach(l => {
      const histLeagueData = getHistLeague(l);
      const found = histLeagueData.find(c => namesMatch(c.name, histLookupName) || namesMatch(c.name, effectiveName));
      if (found) {
        histByLeague[l] = found;
        histTotalPts += found.total || 0;
      }
    });

    const histChampions = Object.values(histByLeague).flatMap(f => (f.champions || []));
    const histRelegated = Object.values(histByLeague).flatMap(f => (f.relegated || []));
    const histLeagueNames = Object.keys(histByLeague);
    const multiLeague = histLeagueNames.length > 1;

    let playoffsCount = 0;
    Object.values(histByLeague).forEach(found => {
      Object.entries(found.bySeason || {}).forEach(([s, pts]) => {
        const sNum = parseInt(s);
        const threshold = sNum <= 29 ? 1 : 3;
        if (pts >= threshold) playoffsCount++;
      });
    });
    db.seasons.forEach(s => {
      const bp = computeBonusPoints(s, leagueName)[carId] || 0;
      if (bp >= 3) playoffsCount++;
    });

    function handlePhoto(e) {
      const file = e.target.files[0];
      if (!file) return;
      const reader = new FileReader();
      if (!isPublicMode) uploadToCloudinary(file).then(url => setCarPhoto(carId, url));
    }

    return (
      <div className="car-profile-modal" onClick={() => setProfileCar(null)}>
        <div className="car-profile-card" onClick={e => e.stopPropagation()}>
          {/* Header */}
          <div className="car-profile-header">
            <label className="car-photo-box" title={isPublicMode ? '' : "Cliquer pour changer la photo"} style={{ cursor: isPublicMode ? 'default' : 'pointer' }}>
              {photo
                ? <img src={photo} alt={effectiveName} style={{ position:'absolute',inset:0,width:'100%',height:'100%',objectFit:'cover',objectPosition:'center' }} />
                : <span style={{ fontSize:28,color:'var(--text-dim)' }}>🚗</span>}
              {!isPublicMode && <div className="car-photo-overlay">📷</div>}
              {!isPublicMode && <input type="file" accept="image/*" style={{ display:'none' }} onChange={handlePhoto} />}
            </label>
            <div style={{ flex:1 }}>
              <div className="font-bebas" style={{ fontSize:22,color:'var(--gold)',letterSpacing:3 }}>{effectiveName}</div>
              <div className="text-dim" style={{ fontSize:12 }}>{(() => {
                let foundLeague = null;
                for (const l of [...LEAGUES, ...AUXILIARY_LEAGUES]) {
                  const league = currentSeason.leagues[l];
                  if (!league) continue;
                  const c = league.cars.find(c => c.id === carId || c.name.toLowerCase() === effectiveName.toLowerCase());
                  if (c) { foundLeague = l; break; }
                }
                return foundLeague || leagueName;
              })()}</div>
              <div style={{ marginTop:6,display:'flex',gap:6,flexWrap:'wrap',alignItems:'center' }}>
                {(champCount + histChampions.length) > 0 && <span className="badge badge-gold">🏆 ×{champCount + histChampions.length}</span>}
                {(relCount + histRelegated.length) > 0 && <span className="badge badge-red">⬇ ×{relCount + histRelegated.length}</span>}
                {(() => {
                  const allBonus = computeAllSeasonsBonus(leagueName);
                  const rank = allBonus.findIndex(e => e.name.toLowerCase() === effectiveName.toLowerCase());
                  const total = histTotalPts + totalBonusPts;
                  return total > 0 ? (
                    <span className="badge badge-blue">
                      #{rank + 1} · {total} pts annexes
                    </span>
                  ) : null;
                })()}
              </div>
            </div>
            <button className="btn btn-dark btn-sm" onClick={() => setProfileCar(null)}>✕</button>
          </div>

          {/* App stats note */}
          <div style={{ padding:'6px 16px',background:'rgba(201,168,76,0.06)',borderBottom:'1px solid var(--border)',fontSize:11,color:'var(--gold-dim)',letterSpacing:1,fontFamily:"'Bebas Neue',sans-serif" }}>
            ★ STATISTIQUES DE MATCHS À PARTIR DE S33
          </div>

          {/* Stats grid */}
          <div className="car-stat-grid">
            {[
              { val: totalGP, lbl: 'Matchs joués' },
              { val: totalW, lbl: 'Victoires' },
              { val: totalD, lbl: 'Nuls' },
              { val: totalL, lbl: 'Défaites' },
              { val: `${winPct}%`, lbl: 'Taux victoire' },
              { val: totalGF, lbl: 'Buts pour' },
              { val: totalGA, lbl: 'Buts contre' },
              { val: diff >= 0 ? `+${diff}` : `${diff}`, lbl: 'Différence' },
              { val: playoffsCount, lbl: 'Participations playoffs' },
            ].map((st, i) => (
              <div key={i} className="car-stat-item">
                <div className="val" style={st.val?.toString().startsWith('+') ? { color: 'var(--green)' } : st.val?.toString().startsWith('-') ? { color: '#e74c3c' } : {}}>{st.val}</div>
                <div className="lbl">{st.lbl}</div>
              </div>
            ))}
          </div>

          {/* Points Annexes par ligue */}
          {(() => {
            const allLeagueData = {}; // leagueName -> { seasonPts: {n: pts}, champions: [], relegated: [], total }

            Object.entries(histByLeague).forEach(([l, found]) => {
              if (!allLeagueData[l]) allLeagueData[l] = { seasonPts: {}, champions: [], relegated: [], total: 0 };
              Object.entries(found.bySeason).forEach(([s, pts]) => {
                allLeagueData[l].seasonPts[parseInt(s)] = pts;
              });
              allLeagueData[l].champions.push(...(found.champions || []));
              allLeagueData[l].relegated.push(...(found.relegated || []));
              allLeagueData[l].total += found.total;
            });

            const allAppLeagues = [...LEAGUES, ...AUXILIARY_LEAGUES];
            allAppLeagues.forEach(lName => {
              db.seasons.forEach(s => {
                const league = s.leagues[lName];
                if (!league) return;
                const car = league.cars.find(c => c.id === carId);
                if (!car) return;
                const bp = computeBonusPoints(s, lName)[carId] || 0;
                const isChamp = s.champions?.[lName] === carId;
                const isRel = s.relegated?.[lName] === carId;
                if (bp > 0 || isChamp || isRel) {
                  if (!allLeagueData[lName]) allLeagueData[lName] = { seasonPts: {}, champions: [], relegated: [], total: 0 };
                  if (bp > 0) {
                    allLeagueData[lName].seasonPts[s.season] = bp;
                    allLeagueData[lName].total += bp;
                  }
                  if (isChamp) allLeagueData[lName].champions.push(s.season);
                  if (isRel) allLeagueData[lName].relegated.push(s.season);
                }
              });
            });

            const leagueKeys = Object.keys(allLeagueData);
            if (leagueKeys.length === 0) return null;

            const grandTotal = Object.values(allLeagueData).reduce((sum, l) => sum + l.total, 0);

            return (
              <div style={{ padding:'0 16px 16px' }}>
                <div style={{ display:'flex',alignItems:'center',justifyContent:'space-between',marginBottom:8 }}>
                  <div className="font-bebas" style={{ fontSize:14,color:'var(--gold-dim)',letterSpacing:2 }}>
                    Points Annexes — Toutes Saisons
                  </div>
                  <div className="font-bebas" style={{ fontSize:22,color:'var(--gold)',letterSpacing:2 }}>
                    {grandTotal} pts
                  </div>
                </div>

                {leagueKeys.sort().map(l => {
                  const ldata = allLeagueData[l];
                  const allSeasonSet = new Set([
                    ...Object.keys(ldata.seasonPts).map(Number),
                    ...(ldata.champions || []),
                    ...(ldata.relegated || []),
                  ]);
                  const seasonNums = [...allSeasonSet].sort((a,b) => a-b);
                  const RECENT = 8;
                  const recentNums = seasonNums.slice(-RECENT);
                  const oldNums = seasonNums.slice(0, -RECENT);
                  return (
                    <BonusLeagueTable key={l} l={l} ldata={ldata} recentNums={recentNums} oldNums={oldNums} />
                  );
                })}

                {/* Grand total if multi-league */}
                {leagueKeys.length > 1 && (
                  <div style={{ textAlign:'right',marginTop:4,fontSize:12,color:'var(--text-dim)',borderTop:'1px solid var(--border)',paddingTop:8 }}>
                    Total général : <span style={{ color:'var(--gold)',fontFamily:"'Bebas Neue',sans-serif",fontSize:20 }}>{grandTotal}</span> pts annexes
                  </div>
                )}
              </div>
            );
          })()}

          {/* App season history (matches) */}
          <div style={{ padding:'0 16px 16px' }}>
            <div className="font-bebas" style={{ fontSize:14,color:'var(--gold-dim)',marginBottom:8,letterSpacing:2 }}>
              Historique Matchs — S33+
            </div>
            <table className="tbl">
              <thead><tr><th>S.</th><th>Grp</th><th>V</th><th>N</th><th>D</th><th>BP</th><th>BC</th><th>Pts Ann.</th><th></th></tr></thead>
              <tbody>
                {db.seasons.map(s => {
                  const l = s.leagues[leagueName];
                  if (!l) return null;
                  const carInSeason = l.cars.find(c => c.id === carId);
                  if (!carInSeason) return null;
                  let w=0,d=0,lo=0,gf=0,ga=0;
                  Object.values(l.groupResults || {}).forEach(ms => ms.forEach(m => {
                    if (m.homeGoals === null) return;
                    if (m.homeId === carId) { gf+=m.homeGoals; ga+=m.awayGoals; if(m.homeGoals>m.awayGoals)w++; else if(m.homeGoals<m.awayGoals)lo++; else d++; }
                    if (m.awayId === carId) { gf+=m.awayGoals; ga+=m.homeGoals; if(m.awayGoals>m.homeGoals)w++; else if(m.awayGoals<m.homeGoals)lo++; else d++; }
                  }));
                  const bp = computeBonusPoints(s, leagueName)[carId] || 0;
                  const isChamp = s.champions[leagueName] === carId;
                  const isRel = s.relegated[leagueName] === carId;
                  return (
                    <tr key={s.season}>
                      <td className="rank">{s.season}</td>
                      <td><span className="badge badge-blue">G{carInSeason.group+1}</span></td>
                      <td>{w}</td><td>{d}</td><td>{lo}</td><td>{gf}</td><td>{ga}</td>
                      <td className="pts-val">{bp}</td>
                      <td>{isChamp && '🏆'}{isRel && '⬇'}</td>
                    </tr>
                  );
                })}
                {db.seasons.length === 0 && (
                  <tr><td colSpan={9} className="text-dim text-center" style={{ padding:12 }}>Aucune saison jouée</td></tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    );
  }

  function carDisplayName(name, leagueName) {
    return name;
  }

  function buildCarRegistry() {
    const activeCars = {};
    LEAGUES.forEach(l => {
      const league = currentSeason.leagues[l];
      if (!league) return;
      league.cars.forEach(c => {
        const key = c.name;
        if (!activeCars[key]) activeCars[key] = { name: c.name, displayName: c.name, leagues: [] };
        activeCars[key].leagues.push({ leagueName: l, carId: c.id, group: c.group });
      });
    });

    const histCars = {};
    LEAGUES.forEach(l => {
      const histLeague = HISTORICAL_DATA.historicalBonus[l] || [];
      histLeague.forEach(c => {
        const key = c.name;
        if (!histCars[key]) histCars[key] = { name: c.name, displayName: carDisplayName(c.name, l), champions: [], relegated: [] };
        (c.champions || []).forEach(s => { histCars[key].champions.push({ season: s, league: l }); });
        (c.relegated || []).forEach(s => { histCars[key].relegated.push({ season: s, league: l }); });
      });
    });

    const appRelByName = {}; // name -> [{ season, league }]
    db.seasons.forEach(s => {
      LEAGUES.forEach(l => {
        const relId = s.relegated?.[l];
        if (!relId) return;
        const league = s.leagues[l];
        if (!league) return;
        const relCar = league.cars?.find(c => c.id === relId);
        if (!relCar) return;
        const key = relCar.name;
        if (!appRelByName[key]) appRelByName[key] = [];
        appRelByName[key].push({ season: s.season, league: l });
      });
    });

    const active = Object.values(activeCars).map(entry => {
      const histKey = entry.name;
      const hist = histCars[histKey] || null;
      const histRels = hist ? hist.relegated.slice() : [];
      const appRels = appRelByName[histKey] || [];
      const relegations = [...histRels, ...appRels].sort((a,b) => a.season - b.season);
      return { ...entry, hist, relegations };
    }).sort((a, b) => a.name.localeCompare(b.name));

    const activeNameKeys = new Set(Object.keys(activeCars));

    const relegatedGone = Object.entries(histCars)
      .filter(([key]) => !activeNameKeys.has(key))
      .map(([key, hist]) => {
        const appRels = appRelByName[key] || [];
        const relEvents = [...hist.relegated, ...appRels].sort((a,b) => b.season - a.season);
        const lastRel = relEvents[0] || null;
        return { ...hist, lastRelSeason: lastRel?.season || null, lastRelLeague: lastRel?.league || null, leagues: [], relegations: relEvents };
      })
      .filter(e => e.lastRelSeason !== null)
      .sort((a, b) => b.lastRelSeason - a.lastRelSeason);

    Object.entries(appRelByName).forEach(([name, rels]) => {
      if (activeNameKeys.has(name)) return; // encore active
      if (histCars[name]) return; // déjà dans relegatedGone via histCars
      const relEvents = rels.slice().sort((a,b) => b.season - a.season);
      const lastRel = relEvents[0];
      relegatedGone.push({ name, displayName: name, champions: [], relegated: relEvents, lastRelSeason: lastRel.season, lastRelLeague: lastRel.league, leagues: [], relegations: relEvents });
    });
    relegatedGone.sort((a, b) => b.lastRelSeason - a.lastRelSeason);

    const returned = active.filter(e => e.relegations.length > 0);

    return { active, relegatedGone, returned };
  }

  function BonusView() {
    const [search, setSearch] = useState('');
    const [statusFilter, setStatusFilter] = useState(null);
    const [sortBySeason, setSortBySeason] = useState(null);
    const bonusScrollRef = React.useRef(null);

    React.useEffect(() => {
      if (bonusScrollRef.current) {
        bonusScrollRef.current.scrollLeft = bonusScrollPos.current;
      }
    });

    const allBonus = computeAllSeasonsBonus(leagueTab);
    const histLeague = getHistLeague(leagueTab);
    const histSeasons = new Set();
    histLeague.forEach(c => Object.keys(c.bySeason).forEach(s => histSeasons.add(parseInt(s))));
    const histSeasonNums = [...histSeasons].sort((a,b) => a-b);
    const appSeasonNums = db.seasons.map(s => s.season);

    const allSeasonKeys = [
      ...histSeasonNums.map(n => `hist-S${n}`),
      ...appSeasonNums.map(n => `app-S${n}`)
    ];
    const sortedBonus = sortBySeason ? [...allBonus].sort((a, b) => {
      const keysUpTo = allSeasonKeys.slice(0, allSeasonKeys.indexOf(sortBySeason) + 1);
      const totalA = keysUpTo.reduce((sum, k) => sum + (a.bySeason[k] || 0), 0);
      const totalB = keysUpTo.reduce((sum, k) => sum + (b.bySeason[k] || 0), 0);
      return totalB - totalA;
    }) : allBonus;

    const registry = buildCarRegistry();
    const activeInThisLeagueSet = new Set(
      registry.active
        .filter(e => e.leagues.some(l => l.leagueName === leagueTab))
        .map(e => e.name.toLowerCase())
    );
    const activeInOtherLeagueMap = {};
    registry.active
      .filter(e => !e.leagues.some(l => l.leagueName === leagueTab))
      .forEach(e => {
        activeInOtherLeagueMap[e.name.toLowerCase()] = e.leagues[0]?.leagueName;
      });

    const getStatus = (entry) => {
      const nl = entry.name.toLowerCase();
      if (activeInThisLeagueSet.has(nl)) return 'active';
      if (activeInOtherLeagueMap[nl]) return 'other';
      return 'inactive';
    };

    const filtered = sortedBonus.filter(e => {
      if (search && !e.name.toLowerCase().includes(search.toLowerCase())) return false;
      if (statusFilter && getStatus(e) !== statusFilter) return false;
      return true;
    });

    function openProfile(entry) {
      const findInLeague = (l) => {
        for (const s of db.seasons) {
          const f = s.leagues[l]?.cars.find(c =>
            c.id === entry.id || namesMatch(c.name, entry.name)
          );
          if (f) return { leagueName: l, carId: f.id };
        }
        return null;
      };
      const inThis = findInLeague(leagueTab);
      if (inThis) { setProfileCar(inThis); return; }
      for (const l of LEAGUES.filter(l => l !== leagueTab)) {
        const found = findInLeague(l);
        if (found) { setProfileCar(found); return; }
      }
      openProfileCar({ leagueName: leagueTab, carId: entry.id, histName: entry.name });
    }

    return (
      <div>
        <div className="section-title">Points Annexes — {leagueTab} — Historique Complet</div>
        <div className="card">
          <div style={{ padding:'8px 12px',borderBottom:'1px solid var(--border)',display:'flex',gap:12,alignItems:'center',flexWrap:'wrap' }}>
            <input
              placeholder="🔍 Rechercher une voiture..."
              value={search}
              onChange={e => setSearch(e.target.value)}
              style={{ width:200 }}
            />
            <span className="font-bebas" style={{ fontSize:13,color:'var(--text-dim)' }}>
              {filtered.length}/{allBonus.length} voitures
            </span>
            <span className="font-bebas" style={{ fontSize:13,color:'var(--green)' }}>
              {allBonus.filter(e => activeInThisLeagueSet.has(e.name.toLowerCase())).length} actives
            </span>
            <span style={{ fontSize:11,display:'flex',gap:6,alignItems:'center',flexWrap:'wrap' }}>
              {[
                { key: 'active',   color: '#2ecc71', label: 'Active' },
                { key: 'other',    color: '#f1c40f', label: 'Autre ligue' },
                { key: 'inactive', color: '#e74c3c', label: 'Inactive' },
              ].map(({ key, color, label }) => (
                <span key={key} onClick={() => setStatusFilter(statusFilter === key ? null : key)}
                  style={{ display:'flex',alignItems:'center',gap:4,cursor:'pointer',padding:'2px 8px',borderRadius:12,background:statusFilter === key ? color + '30' :'transparent',border:statusFilter === key ? `1px solid ${color}` :'1px solid transparent',color:statusFilter === key ? color :'var(--text-dim)',transition:'all 0.15s' }}>
                  <span style={{ display:'inline-block',width:8,height:8,borderRadius:'50%',background:color }} />
                  {label}
                </span>
              ))}
              <span style={{ borderLeft:'1px solid var(--border)',paddingLeft:10,color:'var(--text-dim)' }}><span style={{ color:'var(--green)',marginRight:3 }}>■</span>Champion</span>
              <span style={{ color:'var(--text-dim)' }}><span style={{ color:'#e74c3c',marginRight:3 }}>■</span>Relégué</span>
            </span>
            {search && (
              <button className="btn btn-dark btn-xs" onClick={() => setSearch('')}>✕ Effacer</button>
            )}
          </div>
          <div className="card-body" style={{ padding:0,overflowX:'auto' }} ref={bonusScrollRef} onScroll={e => { bonusScrollPos.current = e.target.scrollLeft; }}>
            <table className="tbl">
              <thead>
                <tr>
                  <th style={{ textAlign:'center',fontSize:11,color:'var(--text-dim)',width:32 }}>Δ</th>
                  <th className="rank" style={{ width:36 }}>#</th>
                  <th style={{ width:60 }}></th>
                  <th className="sticky-col car-name" style={{ left:0,minWidth:140 }}>Voiture</th>
                  <th style={{ textAlign:'center' }}>🏆</th>
                  <th style={{ textAlign:'center' }}>⬇</th>
                  <th className="sticky-col pts-val" style={{ left:140,color:!sortBySeason ? 'var(--gold)' :'var(--gold-dim)',cursor:'pointer',minWidth:60,borderRight:'1px solid var(--border)' }} onClick={() => setSortBySeason(null)}>
                    {!sortBySeason ? '▼ ' : ''}Total
                  </th>
                  {histSeasonNums.map(n => {
                    const key = `hist-S${n}`;
                    const active = sortBySeason === key;
                    return (
                      <th key={`h${n}`} onClick={() => setSortBySeason(active ? null : key)}
                        style={{ textAlign:'center',color:active ? 'var(--gold)' :'var(--text-dim)',minWidth:34,fontSize:11,cursor:'pointer',background:active ? 'rgba(201,168,76,0.15)' :'transparent',userSelect:'none' }}>
                        {active ? '▼ ' : ''}S{n}
                      </th>
                    );
                  })}
                  {appSeasonNums.map(n => {
                    const key = `app-S${n}`;
                    const active = sortBySeason === key;
                    return (
                      <th key={`a${n}`} onClick={() => setSortBySeason(active ? null : key)}
                        style={{ textAlign:'center',color:active ? 'var(--gold)' :'var(--gold-dim)',minWidth:34,fontSize:11,cursor:'pointer',background:active ? 'rgba(201,168,76,0.15)' :'transparent',userSelect:'none' }}>
                        {active ? '▼ ' : ''}S{n}★
                      </th>
                    );
                  })}
                </tr>
              </thead>
              <tbody>
                {(() => {
                  const allSeasonKeys = [
                    ...histSeasonNums.map(n => `hist-S${n}`),
                    ...appSeasonNums.map(n => `app-S${n}`)
                  ];
                  const prevKeys = allSeasonKeys.slice(0, -1);
                  const rankPrev = {};
                  if (prevKeys.length > 0) {
                    const totals = allBonus.map(e => ({
                      id: e.id || e.name,
                      total: prevKeys.reduce((sum, sk) => sum + (e.bySeason[sk] || 0), 0)
                    }));
                    totals.sort((a, b) => b.total - a.total);
                    totals.forEach((t) => {
                      rankPrev[t.id] = totals.filter(o => o.total > t.total).length + 1;
                    });
                  }

                  return filtered.map((entry) => {
                    const photo = !entry.historicalOnly
                      ? (getCarPhoto(entry.id) || getCarPhotoByName(entry.name))
                      : getCarPhotoByName(entry.name);
                    const champCount = (entry.histChampions || []).length;
                    const relCount = (entry.histRelegated || []).length;
                  const rank = (() => {
                    const keysUpTo = sortBySeason
                      ? allSeasonKeys.slice(0, allSeasonKeys.indexOf(sortBySeason) + 1)
                      : null;
                    const myTotal = keysUpTo
                      ? keysUpTo.reduce((sum, k) => sum + (entry.bySeason[k] || 0), 0)
                      : entry.total;
                    const ref = keysUpTo ? sortedBonus : allBonus;
                    return ref.filter(e => {
                      const t = keysUpTo
                        ? keysUpTo.reduce((sum, k) => sum + (e.bySeason[k] || 0), 0)
                        : e.total;
                      return t > myTotal;
                    }).length + 1;
                  })();
                    const entryId = entry.id || entry.name;
                    const prevRank = rankPrev[entryId];
                    const delta = prevRank ? prevRank - rank : null;

                    const entryStatus = getStatus(entry);
                    let statusDot, statusTitle;
                    const nameLower = entry.name.toLowerCase();
                    if (entryStatus === 'active') {
                      statusDot = '#2ecc71'; statusTitle = 'Active dans cette ligue';
                    } else if (entryStatus === 'other') {
                      statusDot = '#f1c40f'; statusTitle = `Active en ${activeInOtherLeagueMap[nameLower]}`;
                    } else {
                      statusDot = '#e74c3c'; statusTitle = 'Inactive';
                    }

                    return (
                      <tr key={entry.id} style={{ cursor:'pointer' }} onClick={() => openProfile(entry)}>
                        <td style={{ textAlign:'center',fontSize:11,width:32 }}>
                          {delta === null || delta === 0
                            ? <span style={{ color:'var(--text-dim)' }}>—</span>
                            : delta > 0
                            ? <span style={{ color:'var(--green)' }}>▲{delta}</span>
                            : <span style={{ color:'#e74c3c' }}>▼{Math.abs(delta)}</span>}
                        </td>
                        <td className="rank" style={{ width:36 }}>
                          {(() => {
                            const sameRank = sortedBonus.filter(e => e.total === entry.total).length > 1;
                            return sameRank ? `=${rank}` : rank;
                          })()}
                        </td>
                        <td style={{ padding:'4px 4px',width:60 }}>
                          <CarThumb photo={photo} />
                        </td>
                        <td className="sticky-col car-name" style={{ whiteSpace:'nowrap',color:'var(--text)',left:0,minWidth:140 }}>
                          <span title={statusTitle} style={{ display:'inline-block',width:9,height:9,borderRadius:'50%',background:statusDot,marginRight:7,verticalAlign:'middle',flexShrink:0 }} />
                          {entry.name}
                        </td>
                        <td style={{ textAlign:'center',fontSize:14,color:'var(--gold)' }}>
                          {champCount > 0 ? `🏆×${champCount}` : '—'}
                        </td>
                        <td style={{ textAlign:'center',fontSize:14,color:'#e74c3c' }}>
                          {relCount > 0 ? `⬇×${relCount}` : '—'}
                        </td>
                        <td className="sticky-col pts-val" style={{ left:140,borderRight:'1px solid var(--border)' }}>{entry.total}</td>
                        {histSeasonNums.map(n => {
                          const pts = entry.bySeason[`hist-S${n}`];
                          const isChamp = (entry.histChampions || []).includes(n);
                          const isRel = (entry.histRelegated || []).includes(n);
                          return (
                            <td key={`h${n}`} style={{
                              textAlign:'center',fontSize:12,color:pts ? (isChamp ? 'var(--green)' :isRel ? '#e74c3c' :'var(--gold)') :'var(--text-dim)',background:isChamp ? 'rgba(39,174,96,0.12)' :isRel ? 'rgba(192,57,43,0.12)' :'transparent',fontWeight:(isChamp || isRel) ? 700 :400
                            }}>
                              {pts || '—'}
                            </td>
                          );
                        })}
                        {appSeasonNums.map(n => {
                          const pts = entry.bySeason[`app-S${n}`];
                          const isChamp = (entry.appChampions || []).includes(n);
                          const isRel = (entry.appRelegated || []).includes(n);
                          return (
                            <td key={`a${n}`} style={{
                              textAlign:'center',fontSize:12,color:(isChamp || pts) ? (isChamp ? 'var(--green)' :isRel ? '#e74c3c' :'var(--gold)') :isRel ? '#e74c3c' :'var(--text-dim)',background:isChamp ? 'rgba(39,174,96,0.12)' :isRel ? 'rgba(192,57,43,0.12)' :'transparent',fontWeight:(isChamp || isRel) ? 700 :400
                            }}>
                              {pts || (isChamp ? '🏆' : isRel ? '⬇' : '—')}
                            </td>
                          );
                        })}
                      </tr>
                    );
                  });
                })()}
                {filtered.length === 0 && (
                  <tr><td colSpan={7 + histSeasonNums.length + appSeasonNums.length} className="text-dim text-center" style={{ padding:24 }}>Aucune voiture trouvée</td></tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    );
  }

  function SuccesseursView() {
    const leagueName = 'Successeurs';
    const league = currentSeason.leagues['Successeurs'];
    const cars = league?.cars || [];
    const playedMatches = league?.matches || []; // Seulement les joués
    const [subTab, setSubTab] = [succSubTab, setSuccSubTab];
    const [openDay, setOpenDay] = useState(null);
    const [search, setSearch] = useState('');
    const [matchSearch, setMatchSearch] = useState('');

    const getName = id => cars.find(c => c.id === id)?.name || id;

    const allMatches = React.useMemo(() => {
      if (cars.length === 0) return [];
      return genRoundRobin(cars).map(m => {
        const p = playedMatches.find(s => s.homeId === m.homeId && s.awayId === m.awayId);
        return p ? { ...m, homeGoals: p.homeGoals, awayGoals: p.awayGoals } : m;
      });
    }, [cars.map(c=>c.id).join(','), playedMatches.map(m => m.homeId + m.homeGoals + '-' + m.awayGoals).join('|')]);

    const standings = cars.map(car => {
      const cm = allMatches.filter(m => m.homeId === car.id || m.awayId === car.id);
      let w = 0, d = 0, l = 0, gf = 0, ga = 0;
      cm.forEach(m => {
        if (m.homeGoals === null) return;
        const isHome = m.homeId === car.id;
        const f = isHome ? m.homeGoals : m.awayGoals;
        const a = isHome ? m.awayGoals : m.homeGoals;
        gf += f; ga += a;
        if (f > a) w++; else if (f === a) d++; else l++;
      });
      return { ...car, pts: w * 3 + d, w, d, l, gf, ga, diff: gf - ga, gp: w + d + l };
    }).sort((a, b) => b.pts - a.pts || b.diff - a.diff || b.gf - a.gf);

    const filteredStandings = search ? standings.filter(c => c.name.toLowerCase().includes(search.toLowerCase())) : standings;
    const playedCount = allMatches.filter(m => m.homeGoals !== null).length;
    const totalCount = allMatches.length;
    const days = [...new Set(allMatches.map(m => m.day))].sort((a, b) => a - b);

    function savePlayedMatches(updatedMatches) {
      const played = updatedMatches.filter(m => m.homeGoals !== null).map(m => ({
        homeId: m.homeId, awayId: m.awayId, homeGoals: m.homeGoals, awayGoals: m.awayGoals
      }));
      setDb(prev => {
        const next = JSON.parse(JSON.stringify(prev));
        next.seasons[next.currentSeasonIdx].leagues['Successeurs'].matches = played;
        return next;
      });
    }

    function simDay(day) {
      const updated = allMatches.map(m => {
        if (m.day === day && m.homeGoals === null) { const s = simScore(); return { ...m, homeGoals: s.h, awayGoals: s.a }; }
        return m;
      });
      savePlayedMatches(updated);
    }

    function simAll() {
      const updated = allMatches.map(m => {
        if (m.homeGoals === null) { const s = simScore(); return { ...m, homeGoals: s.h, awayGoals: s.a }; }
        return m;
      });
      savePlayedMatches(updated);
    }

    function updateMatch(matchId, hg, ag) {
      const updated = allMatches.map(m => m.id === matchId ? { ...m, homeGoals: hg, awayGoals: ag } : m);
      savePlayedMatches(updated);
    }

    const TH = ({ children, color = 'var(--gold-dim)', left = false }) => (
      <th style={{ fontFamily:"'Bebas Neue',sans-serif",fontSize:13,color,letterSpacing:1,padding:'10px 6px',textAlign:left ? 'left' :'center',borderBottom:'2px solid var(--border)',background:'var(--dark3)',whiteSpace:'nowrap',fontWeight:400 }}>{children}</th>
    );

    return (
      <div>
        <div className="section-title">Successeurs</div>

        <div className="tabs" style={{ background:'var(--dark3)',borderBottom:'1px solid var(--border)' }}>
          <button className={`tab ${subTab === 'classement' ? 'active' : ''}`} onClick={() => setSubTab('classement')}>📊 Classement</button>
          <button className={`tab ${subTab === 'matchs' ? 'active' : ''}`} onClick={() => setSubTab('matchs')}>⚽ Matchs ({playedCount}/{totalCount})</button>
          <button className="btn btn-gold btn-sm" style={{ margin:'6px 12px', display: isPublicMode ? 'none' : undefined }} onClick={() => { if(!isPublicMode) simAll(); }}>⚡ Simuler tous les matchs</button><button className="btn btn-sm btn-sim" style={{ margin:'6px 0', display: isPublicMode ? 'none' : undefined }} onClick={() => { if(isPublicMode) return; const nextDay = days.find(d => allMatches.filter(m => m.day === d).some(m => m.homeGoals === null)); if (nextDay !== undefined) simDay(nextDay); }}>📅 Journée suivante</button>
        </div>

        {/* CLASSEMENT */}
        {subTab === 'classement' && (
          <div>
            <div className="card" style={{ marginBottom:10 }}>
              <div style={{ padding:'8px 12px',display:'flex',gap:12,alignItems:'center',flexWrap:'wrap' }}>
                <input placeholder="🔍 Rechercher..." value={search} onChange={e => setSearch(e.target.value)} style={{ width:220 }} />
                <span style={{ fontSize:12,color:'var(--text-dim)' }}>{cars.length} voitures · {playedCount}/{totalCount} matchs</span>

              </div>
            </div>
            <div className="card">
              <div>
                    {filteredStandings.map(s => {
                      const rank = standings.findIndex(c => c.id === s.id) + 1;
                      const promoted = rank <= 4;
                      const sucSucc = rank >= 73;
                      const actuelles = rank >= 25 && rank < 73;
                      const borderColor = promoted ? 'var(--green)' : sucSucc ? '#e74c3c' : actuelles ? 'var(--gold-dim)' : 'transparent';
                      const photo = getCarPhoto(s.id);
                      const badge = promoted ? { label:'▲ PROMU', bg:'rgba(39,174,96,0.25)', color:'var(--green)' }
                                  : sucSucc ? { label:'⬇⬇ SUC.SUCC', bg:'rgba(192,57,43,0.25)', color:'#e74c3c' }
                                  : actuelles ? { label:'⬇ ACTUELLES', bg:'rgba(201,168,76,0.2)', color:'var(--gold)' }
                                  : (() => { const mv = getCarMovement(s.id, leagueName); if (mv === 'promoted') return { label:'▲ PROMU', bg:'rgba(39,174,96,0.25)', color:'var(--green)' }; if (mv === 'relegated') return { label:'⬇ RELÉGUÉ', bg:'rgba(192,57,43,0.25)', color:'#e74c3c' }; return null; })();
                      return (
                        <LeaderboardRow key={s.id}
                          rank={rank} rankDiff={null}
                          carId={s.id} leagueName={leagueName}
                          name={s.name} photo={photo} badge={badge}
                          pts={s.pts} w={s.w} d={s.d} l={s.l}
                          gf={s.gf} ga={s.ga} gp={s.gp}
                          borderColor={borderColor}
                          onClick={() => openProfileCar({ leagueName: 'Successeurs', carId: s.id })}
                        />
                      );
                    })}
              </div>
              <div style={{ padding:'8px 12px',fontSize:11,display:'flex',gap:12,flexWrap:'wrap',color:'var(--text-dim)' }}>
                <span><span style={{ color:'var(--green)',marginRight:3 }}>■</span>Top 4 → Promus V1/V2/V3/V4</span>
                <span><span style={{ color:'#c9a84c',marginRight:3 }}>■</span>25-72 → Actuelles 1-12</span>
                <span><span style={{ color:'#e74c3c',marginRight:3 }}>■</span>73-84 → Successeurs aux Successeurs</span>
              </div>
            </div>
          </div>
        )}

        {/* MATCHS */}
        {subTab === 'matchs' && (
          <div>
            <div className="card" style={{ marginBottom:10 }}>
              <div style={{ padding:'8px 12px' }}>
                <input placeholder="🔍 Filtrer par voiture..." value={matchSearch} onChange={e => setMatchSearch(e.target.value)} style={{ width:250 }} />
              </div>
            </div>
            <div className="card">
              <div>
                {days.map(day => {
                  const dayMatches = allMatches.filter(m => m.day === day);
                  const filteredDay = matchSearch
                    ? dayMatches.filter(m => getName(m.homeId).toLowerCase().includes(matchSearch.toLowerCase()) || getName(m.awayId).toLowerCase().includes(matchSearch.toLowerCase()))
                    : dayMatches;
                  if (filteredDay.length === 0) return null;
                  const dayPlayed = dayMatches.filter(m => m.homeGoals !== null).length;
                  const dayComplete = dayPlayed === dayMatches.length;
                  const isOpen = openDay === day;
                  return (
                    <div key={day} style={{ marginBottom:3 }}>
                      <div onClick={() => {
  const scrollY = window.scrollY;
  document.body.style.position = 'fixed';
  document.body.style.top = `-${scrollY}px`;
  document.body.style.width = '100%';
  setOpenDay(isOpen ? null : day);
  requestAnimationFrame(() => {
    document.body.style.position = '';
    document.body.style.top = '';
    document.body.style.width = '';
    window.scrollTo(0, scrollY);
  });
}}
                        style={{ display:'flex',alignItems:'center',gap:8,padding:'7px 10px',cursor:'pointer',borderRadius:isOpen ? '3px 3px 0 0' :3,background:isOpen ? 'rgba(201,168,76,0.1)' :'var(--dark3)',border:`1px solid ${isOpen ? 'var(--gold-dim)' :'var(--border)'}`,transition:'all 0.15s',userSelect:'none' }}>
                        <span style={{ fontFamily:"'Bebas Neue',sans-serif",letterSpacing:2,fontSize:14,color:isOpen ? 'var(--gold)' :'var(--text-dim)' }}>
                          Journée {day}
                        </span>
                        <span style={{ flex:1 }} />
                        {dayComplete
                          ? <span className="badge badge-green" style={{ fontSize:10 }}>✓ Complète</span>
                          : <span className="text-dim" style={{ fontSize:11 }}>{dayPlayed}/{dayMatches.length}</span>}
                        {!dayComplete && (
                          <button className="btn btn-xs btn-sim" style={{ marginLeft:4 }}
                            onClick={e => { e.stopPropagation(); if(isPublicMode) return; const sy = window.scrollY; simDay(day); setOpenDay(day); requestAnimationFrame(() => requestAnimationFrame(() => window.scrollTo(0, sy))); }} style={{ display: isPublicMode ? 'none' : undefined }}>
                            🎲
                          </button>
                        )}
                        <span style={{ color:'var(--text-dim)',fontSize:11,marginLeft:4 }}>{isOpen ? '▲' : '▼'}</span>
                      </div>
                      <div style={{ border:'1px solid var(--gold-dim)',borderTop:'none',borderRadius:'0 0 3px 3px',background:'var(--dark2)',padding:'4px 6px',display:isOpen?'block':'none' }}>
                          {filteredDay.map(m => {
                            const isPlayed = m.homeGoals !== null;
                            const hWin = isPlayed && m.homeGoals > m.awayGoals;
                            const aWin = isPlayed && m.awayGoals > m.homeGoals;
                            const homePhoto = getCarPhoto(m.homeId);
                            const awayPhoto = getCarPhoto(m.awayId);
                            const homeStats = getCarStats(m.homeId, allMatches);
                            const awayStats = getCarStats(m.awayId, allMatches);
                            const homeRank = standings.findIndex(s => s.id === m.homeId) + 1;
                            const awayRank = standings.findIndex(s => s.id === m.awayId) + 1;
                            const homePts = standings.find(s => s.id === m.homeId)?.pts ?? 0;
                            const awayPts = standings.find(s => s.id === m.awayId)?.pts ?? 0;
                            return (
                              <div key={m.id}
                                onClick={() => openMatchModal({
                                  homeName: getName(m.homeId), awayName: getName(m.awayId),
                                  homePhoto, awayPhoto,
                                  homeGoals: m.homeGoals, awayGoals: m.awayGoals,
                                  homeStats, awayStats,
                                  homeRank, awayRank, homePts, awayPts,
                                  homeQual: null, awayQual: null,
                                  onConfirm: (hg, ag) => updateMatch(m.id, hg, ag),
                                })}
                                style={{ display:'flex',alignItems:'center',gap:8,padding:'8px 10px',borderBottom:'1px solid #1a1a1a',cursor:'pointer',borderLeft:isPlayed ? '3px solid var(--green)' :'3px solid transparent',background:isPlayed ? 'rgba(39,174,96,0.03)' :'transparent',borderRadius:3,transition:'background 0.1s' }}>
                                <div style={{ flex:1,display:'flex',alignItems:'center',gap:6,justifyContent:'flex-end' }}>
                                  <div style={{ fontSize:12,fontWeight:600,textAlign:'right',color:hWin ? 'var(--green)' :aWin ? 'var(--text-dim)' :'var(--text)',lineHeight:1.2 }}>{getName(m.homeId)}</div>
                                  <CarThumb photo={homePhoto} size={40} />
                                </div>
                                <div style={{ fontFamily:"'Bebas Neue',sans-serif",fontSize:20,flexShrink:0,minWidth:52,textAlign:'center',letterSpacing:2,display:'flex',alignItems:'center',justifyContent:'center',gap:2 }}>
                                  {isPlayed ? (
                                    <>
                                      <span style={{ color:hWin ? 'var(--green)' :aWin ? '#e74c3c' :'var(--gold)' }}>{m.homeGoals}</span>
                                      <span style={{ color:'var(--text-dim)' }}> : </span>
                                      <span style={{ color:aWin ? 'var(--green)' :hWin ? '#e74c3c' :'var(--gold)' }}>{m.awayGoals}</span>
                                    </>
                                  ) : <span style={{ color:'var(--text-dim)' }}>— : —</span>}
                                </div>
                                <div style={{ flex:1,display:'flex',alignItems:'center',gap:6 }}>
                                  <CarThumb photo={awayPhoto} size={40} />
                                  <div style={{ fontSize:12,fontWeight:600,color:aWin ? 'var(--green)' :hWin ? 'var(--text-dim)' :'var(--text)',lineHeight:1.2 }}>{getName(m.awayId)}</div>
                                </div>
                              </div>
                            );
                          })}
                        </div>
                    </div>
                  );
                })}
              </div>
            </div>
          </div>
        )}
      </div>
    );
  }

  function AddCarButton({ leagueName }) {
    const [adding, setAdding] = React.useState(false);
    const [newName, setNewName] = React.useState('');

    const league = currentSeason.leagues[leagueName];
    const hasStarted = (league?.matches || []).length > 0;

    function handleAdd() {
      const name = newName.trim();
      if (!name) return;
      setDb(prev => {
        const next = JSON.parse(JSON.stringify(prev));
        const league = next.seasons[next.seasons.length - 1].leagues[leagueName];
        if (!league) return prev;
        if (league.cars.some(c => c.name.toLowerCase() === name.toLowerCase())) {
          alert(`"${name}" existe déjà dans ${leagueName} !`);
          return prev;
        }
        league.cars.push({ id: genId(), name });
        return next;
      });
      setNewName('');
      setAdding(false);
    }

    if (hasStarted) {
      return (
        <button className="btn btn-sm" disabled style={{ marginLeft:'auto',fontSize:12,opacity:0.4,cursor:'not-allowed' }} title="Impossible d'ajouter une voiture en cours de saison">
          🔒 Ajouter une voiture
        </button>
      );
    }

    if (!adding) {
      return (
        <button className="btn btn-sm" onClick={() => { if(!isPublicMode) setAdding(true); }} style={{ marginLeft:'auto',fontSize:12, display: isPublicMode ? 'none' : 'inline-flex' }}>
          ➕ Ajouter une voiture
        </button>
      );
    }
    return (
      <div style={{ display:'flex',gap:6,alignItems:'center',marginLeft:'auto' }}>
        <input
          autoFocus
          placeholder="Nom de la voiture..."
          value={newName}
          onChange={e => setNewName(e.target.value)}
          onKeyDown={e => { if (e.key === 'Enter') handleAdd(); if (e.key === 'Escape') setAdding(false); }}
          style={{ width:180,fontSize:13 }}
        />
        <button className="btn btn-sm btn-green" onClick={handleAdd} style={{ fontSize:12 }}>✓</button>
        <button className="btn btn-sm" onClick={() => { setAdding(false); setNewName(''); }} style={{ fontSize:12 }}>✕</button>
      </div>
    );
  }

  function SucSuccView({ subTab, setSubTab }) {
    const [openDay, setOpenDay] = useState(null);
    const leagueName = 'Successeurs aux Successeurs';
    const league = currentSeason.leagues[leagueName];
    const cars = league?.cars || [];
    const playedMatches = league?.matches || [];
    const [search, setSearch] = useState('');
    const [matchSearch, setMatchSearch] = useState('');

    const getName = id => cars.find(c => c.id === id)?.name || id;

    const allMatches = React.useMemo(() => {
      if (cars.length === 0) return [];
      return genRoundRobin(cars).map(m => {
        const p = playedMatches.find(s => s.homeId === m.homeId && s.awayId === m.awayId);
        return p ? { ...m, homeGoals: p.homeGoals, awayGoals: p.awayGoals } : m;
      });
    }, [cars.map(c => c.id).join(','), playedMatches.map(m => m.homeId + m.homeGoals + '-' + m.awayGoals).join('|')]);

    const standings = cars.map(car => {
      const cm = allMatches.filter(m => m.homeId === car.id || m.awayId === car.id);
      let w = 0, d = 0, l = 0, gf = 0, ga = 0;
      cm.forEach(m => {
        if (m.homeGoals === null) return;
        const isHome = m.homeId === car.id;
        const f = isHome ? m.homeGoals : m.awayGoals;
        const a = isHome ? m.awayGoals : m.homeGoals;
        gf += f; ga += a;
        if (f > a) w++; else if (f === a) d++; else l++;
      });
      return { ...car, pts: w * 3 + d, w, d, l, gf, ga, diff: gf - ga, gp: w + d + l };
    }).sort((a, b) => b.pts - a.pts || b.diff - a.diff || b.gf - a.gf);

    const filteredStandings = search ? standings.filter(c => c.name.toLowerCase().includes(search.toLowerCase())) : standings;
    const playedCount = allMatches.filter(m => m.homeGoals !== null).length;
    const totalCount = allMatches.length;
    const days = [...new Set(allMatches.map(m => m.day))].sort((a, b) => a - b);

    function savePlayedMatches(updatedMatches) {
      const played = updatedMatches.filter(m => m.homeGoals !== null).map(m => ({
        homeId: m.homeId, awayId: m.awayId, homeGoals: m.homeGoals, awayGoals: m.awayGoals
      }));
      setDb(prev => {
        const next = JSON.parse(JSON.stringify(prev));
        next.seasons[next.currentSeasonIdx].leagues[leagueName].matches = played;
        return next;
      });
    }

    function simDay(day) {
      const updated = allMatches.map(m => {
        if (m.day === day && m.homeGoals === null) { const s = simScore(); return { ...m, homeGoals: s.h, awayGoals: s.a }; }
        return m;
      });
      savePlayedMatches(updated);
    }

    function simAll() {
      const updated = allMatches.map(m => {
        if (m.homeGoals === null) { const s = simScore(); return { ...m, homeGoals: s.h, awayGoals: s.a }; }
        return m;
      });
      savePlayedMatches(updated);
    }

    function updateMatch(matchId, hg, ag) {
      const updated = allMatches.map(m => m.id === matchId ? { ...m, homeGoals: hg, awayGoals: ag } : m);
      savePlayedMatches(updated);
    }

    const TH = ({ children, color = 'var(--gold-dim)', left = false }) => (
      <th style={{ fontFamily:"'Bebas Neue',sans-serif",fontSize:13,color,letterSpacing:1,padding:'10px 6px',textAlign:left ? 'left' :'center',borderBottom:'2px solid var(--border)',background:'var(--dark3)',whiteSpace:'nowrap',fontWeight:400 }}>{children}</th>
    );

    return (
      <div>
        <div className="section-title">Successeurs aux Successeurs</div>
        <div className="tabs" style={{ background:'var(--dark3)',borderBottom:'1px solid var(--border)' }}>
          <button className={`tab ${subTab === 'classement' ? 'active' : ''}`} onClick={() => setSubTab('classement')}>📊 Classement</button>
          <button className={`tab ${subTab === 'matchs' ? 'active' : ''}`} onClick={() => setSubTab('matchs')}>⚽ Matchs ({playedCount}/{totalCount})</button>
          <button className="btn btn-gold btn-sm" style={{ margin:'6px 12px', display: isPublicMode ? 'none' : undefined }} onClick={() => { if(!isPublicMode) simAll(); }}>⚡ Simuler tous les matchs</button><button className="btn btn-sm btn-sim" style={{ margin:'6px 0', display: isPublicMode ? 'none' : undefined }} onClick={() => { if(isPublicMode) return; const nextDay = days.find(d => allMatches.filter(m => m.day === d).some(m => m.homeGoals === null)); if (nextDay !== undefined) simDay(nextDay); }}>📅 Journée suivante</button>
        </div>

        {subTab === 'classement' && (
          <div>
            <div className="card" style={{ marginBottom:10 }}>
              <div style={{ padding:'8px 12px',display:'flex',gap:12,alignItems:'center',flexWrap:'wrap' }}>
                <input placeholder="🔍 Rechercher..." value={search} onChange={e => setSearch(e.target.value)} style={{ width:220 }} />
                <span style={{ fontSize:12,color:'var(--text-dim)' }}>{cars.length} voitures · {playedCount}/{totalCount} matchs</span>
              </div>
            </div>
            <div className="card">
              <div>
                    {filteredStandings.map(s => {
                      const rank = standings.findIndex(c => c.id === s.id) + 1;
                      const promoted = rank <= 12;
                      const relegated = rank > 16;
                      const rowBg = promoted ? 'rgba(39,174,96,0.07)' : relegated ? 'rgba(192,57,43,0.09)' : 'transparent';
                      const borderColor = promoted ? 'var(--green)' : relegated ? '#e74c3c' : 'transparent';
                      const photo = getCarPhoto(s.id);
                      const diff = s.gf - s.ga;
                      const td = { padding: '0 6px', borderBottom: '1px solid #1a1a1a', background: rowBg, height: 72 };
                                            const badge = promoted ? { label:'▲', bg:'rgba(39,174,96,0.25)', color:'var(--green)' } : relegated ? { label:'⬇', bg:'rgba(192,57,43,0.25)', color:'#e74c3c' } : null;
                      return (
                        <LeaderboardRow key={s.id}
                          rank={rank} rankDiff={null}
                          carId={s.id} leagueName={'Successeurs'}
                          name={s.name} photo={photo} badge={badge}
                          pts={s.pts} w={s.w} d={s.d} l={s.l}
                          gf={s.gf} ga={s.ga} gp={s.gp}
                          borderColor={borderColor}
                          onClick={() => openProfileCar({ leagueName: 'Successeurs', carId: s.id })}
                        />
                      );
                    })})              </div>
              <div style={{ padding:'8px 12px',fontSize:11,display:'flex',gap:12,flexWrap:'wrap',color:'var(--text-dim)' }}>
                <span><span style={{ color:'var(--green)',marginRight:3 }}>■</span>Top 12 → Successeurs</span>
                <span><span style={{ color:'var(--text-dim)',marginRight:3 }}>■</span>13-16 → Restent</span>
                <span><span style={{ color:'#e74c3c',marginRight:3 }}>■</span>17-32 → Remplaçants des Successeurs</span>
              </div>
            </div>
          </div>
        )}

        {subTab === 'matchs' && (
          <div>
            <div className="card" style={{ marginBottom:10 }}>
              <div style={{ padding:'8px 12px' }}>
                <input placeholder="🔍 Filtrer par voiture..." value={matchSearch} onChange={e => setMatchSearch(e.target.value)} style={{ width:250 }} />
              </div>
            </div>
            <div className="card">
              <div>
                {days.map(day => {
                  const dayMatches = allMatches.filter(m => m.day === day);
                  const filteredDay = matchSearch
                    ? dayMatches.filter(m => getName(m.homeId).toLowerCase().includes(matchSearch.toLowerCase()) || getName(m.awayId).toLowerCase().includes(matchSearch.toLowerCase()))
                    : dayMatches;
                  if (filteredDay.length === 0) return null;
                  const dayPlayed = dayMatches.filter(m => m.homeGoals !== null).length;
                  const dayComplete = dayPlayed === dayMatches.length;
                  const isOpen = openDay === day;
                  return (
                    <div key={day} style={{ marginBottom:3 }}>
                      <div onClick={() => {
  const scrollY = window.scrollY;
  document.body.style.position = 'fixed';
  document.body.style.top = `-${scrollY}px`;
  document.body.style.width = '100%';
  setOpenDay(isOpen ? null : day);
  requestAnimationFrame(() => {
    document.body.style.position = '';
    document.body.style.top = '';
    document.body.style.width = '';
    window.scrollTo(0, scrollY);
  });
}}
                        style={{ display:'flex',alignItems:'center',gap:8,padding:'7px 10px',cursor:'pointer',borderRadius:isOpen ? '3px 3px 0 0' :3,background:isOpen ? 'rgba(201,168,76,0.1)' :'var(--dark3)',border:`1px solid ${isOpen ? 'var(--gold-dim)' :'var(--border)'}`,transition:'all 0.15s',userSelect:'none' }}>
                        <span style={{ fontFamily:"'Bebas Neue',sans-serif",letterSpacing:2,fontSize:14,color:isOpen ? 'var(--gold)' :'var(--text-dim)' }}>
                          Journée {day}
                        </span>
                        <span style={{ flex:1 }} />
                        {dayComplete
                          ? <span className="badge badge-green" style={{ fontSize:10 }}>✓ Complète</span>
                          : <span className="text-dim" style={{ fontSize:11 }}>{dayPlayed}/{dayMatches.length}</span>}
                        {!dayComplete && (
                          <button className="btn btn-xs btn-sim" style={{ marginLeft:4 }}
                            onClick={e => { e.stopPropagation(); if(isPublicMode) return; const sy = window.scrollY; simDay(day); setOpenDay(day); requestAnimationFrame(() => requestAnimationFrame(() => window.scrollTo(0, sy))); }} style={{ display: isPublicMode ? 'none' : undefined }}>
                            🎲
                          </button>
                        )}
                        <span style={{ color:'var(--text-dim)',fontSize:11,marginLeft:4 }}>{isOpen ? '▲' : '▼'}</span>
                      </div>
                      <div style={{ border:'1px solid var(--gold-dim)',borderTop:'none',borderRadius:'0 0 3px 3px',background:'var(--dark2)',padding:'4px 6px',display:isOpen?'block':'none' }}>
                          {filteredDay.map(m => {
                            const isPlayed = m.homeGoals !== null;
                            const hWin = isPlayed && m.homeGoals > m.awayGoals;
                            const aWin = isPlayed && m.awayGoals > m.homeGoals;
                            const homePhoto = getCarPhoto(m.homeId);
                            const awayPhoto = getCarPhoto(m.awayId);
                            const homeStats = getCarStats(m.homeId, allMatches);
                            const awayStats = getCarStats(m.awayId, allMatches);
                            const homeRank = standings.findIndex(s => s.id === m.homeId) + 1;
                            const awayRank = standings.findIndex(s => s.id === m.awayId) + 1;
                            const homePts = standings.find(s => s.id === m.homeId)?.pts ?? 0;
                            const awayPts = standings.find(s => s.id === m.awayId)?.pts ?? 0;
                            return (
                              <div key={m.id}
                                onClick={() => openMatchModal({
                                  homeName: getName(m.homeId), awayName: getName(m.awayId),
                                  homePhoto, awayPhoto,
                                  homeGoals: m.homeGoals, awayGoals: m.awayGoals,
                                  homeStats, awayStats,
                                  homeRank, awayRank, homePts, awayPts,
                                  homeQual: null, awayQual: null,
                                  onConfirm: (hg, ag) => updateMatch(m.id, hg, ag),
                                })}
                                style={{ display:'flex',alignItems:'center',gap:8,padding:'8px 10px',borderBottom:'1px solid #1a1a1a',cursor:'pointer',borderLeft:isPlayed ? '3px solid var(--green)' :'3px solid transparent',background:isPlayed ? 'rgba(39,174,96,0.03)' :'transparent',borderRadius:3,transition:'background 0.1s' }}>
                                <div style={{ flex:1,display:'flex',alignItems:'center',gap:6,justifyContent:'flex-end' }}>
                                  <div style={{ fontSize:12,fontWeight:600,textAlign:'right',color:hWin ? 'var(--green)' :aWin ? 'var(--text-dim)' :'var(--text)',lineHeight:1.2 }}>{getName(m.homeId)}</div>
                                  <CarThumb photo={homePhoto} size={40} />
                                </div>
                                <div style={{ fontFamily:"'Bebas Neue',sans-serif",fontSize:20,flexShrink:0,minWidth:52,textAlign:'center',letterSpacing:2,display:'flex',alignItems:'center',justifyContent:'center',gap:2 }}>
                                  {isPlayed ? (
                                    <>
                                      <span style={{ color:hWin ? 'var(--green)' :aWin ? '#e74c3c' :'var(--gold)' }}>{m.homeGoals}</span>
                                      <span style={{ color:'var(--text-dim)' }}> : </span>
                                      <span style={{ color:aWin ? 'var(--green)' :hWin ? '#e74c3c' :'var(--gold)' }}>{m.awayGoals}</span>
                                    </>
                                  ) : <span style={{ color:'var(--text-dim)' }}>— : —</span>}
                                </div>
                                <div style={{ flex:1,display:'flex',alignItems:'center',gap:6 }}>
                                  <CarThumb photo={awayPhoto} size={40} />
                                  <div style={{ fontSize:12,fontWeight:600,color:aWin ? 'var(--green)' :hWin ? 'var(--text-dim)' :'var(--text)',lineHeight:1.2 }}>{getName(m.awayId)}</div>
                                </div>
                              </div>
                            );
                          })}
                        </div>
                    </div>
                  );
                })}
              </div>
            </div>
          </div>
        )}
      </div>
    );
  }

  function RemplacView({ subTab, setSubTab }) {
    const [openDay, setOpenDay] = useState(null);
    const leagueName = 'Remplaçants des Successeurs';
    const league = currentSeason.leagues[leagueName];
    const cars = league?.cars || [];
    const playedMatches = league?.matches || [];
    const [search, setSearch] = useState('');
    const [matchSearch, setMatchSearch] = useState('');

    const getName = id => cars.find(c => c.id === id)?.name || id;

    const allMatches = React.useMemo(() => {
      if (cars.length === 0) return [];
      return genRoundRobin(cars).map(m => {
        const p = playedMatches.find(s => s.homeId === m.homeId && s.awayId === m.awayId);
        return p ? { ...m, homeGoals: p.homeGoals, awayGoals: p.awayGoals } : m;
      });
    }, [cars.map(c => c.id).join(','), playedMatches.map(m => m.homeId + m.homeGoals + '-' + m.awayGoals).join('|')]);

    const standings = cars.map(car => {
      const cm = allMatches.filter(m => m.homeId === car.id || m.awayId === car.id);
      let w = 0, d = 0, l = 0, gf = 0, ga = 0;
      cm.forEach(m => {
        if (m.homeGoals === null) return;
        const isHome = m.homeId === car.id;
        const f = isHome ? m.homeGoals : m.awayGoals;
        const a = isHome ? m.awayGoals : m.homeGoals;
        gf += f; ga += a;
        if (f > a) w++; else if (f === a) d++; else l++;
      });
      return { ...car, pts: w * 3 + d, w, d, l, gf, ga, diff: gf - ga, gp: w + d + l };
    }).sort((a, b) => b.pts - a.pts || b.diff - a.diff || b.gf - a.gf);

    const filteredStandings = search ? standings.filter(c => c.name.toLowerCase().includes(search.toLowerCase())) : standings;
    const playedCount = allMatches.filter(m => m.homeGoals !== null).length;
    const totalCount = allMatches.length;
    const days = [...new Set(allMatches.map(m => m.day))].sort((a, b) => a - b);

    function savePlayedMatches(updatedMatches) {
      const played = updatedMatches.filter(m => m.homeGoals !== null).map(m => ({
        homeId: m.homeId, awayId: m.awayId, homeGoals: m.homeGoals, awayGoals: m.awayGoals
      }));
      setDb(prev => {
        const next = JSON.parse(JSON.stringify(prev));
        next.seasons[next.currentSeasonIdx].leagues[leagueName].matches = played;
        return next;
      });
    }

    function simDay(day) {
      const updated = allMatches.map(m => {
        if (m.day === day && m.homeGoals === null) { const s = simScore(); return { ...m, homeGoals: s.h, awayGoals: s.a }; }
        return m;
      });
      savePlayedMatches(updated);
    }

    function updateMatch(matchId, hg, ag) {
      const updated = allMatches.map(m => m.id === matchId ? { ...m, homeGoals: hg, awayGoals: ag } : m);
      savePlayedMatches(updated);
    }

    const TH = ({ children, color = 'var(--gold-dim)', left = false }) => (
      <th style={{ fontFamily:"'Bebas Neue',sans-serif",fontSize:13,color,letterSpacing:1,padding:'10px 6px',textAlign:left ? 'left' :'center',borderBottom:'2px solid var(--border)',background:'var(--dark3)',whiteSpace:'nowrap',fontWeight:400 }}>{children}</th>
    );

    return (
      <div>
        <div className="section-title">Remplaçants des Successeurs</div>
        <div className="tabs" style={{ background:'var(--dark3)',borderBottom:'1px solid var(--border)' }}>
          <button className={`tab ${subTab === 'classement' ? 'active' : ''}`} onClick={() => setSubTab('classement')}>📊 Classement</button>
          <button className={`tab ${subTab === 'matchs' ? 'active' : ''}`} onClick={() => setSubTab('matchs')}>⚽ Matchs ({playedCount}/{totalCount})</button>
          <button className="btn btn-gold btn-sm" style={{ margin:'6px 12px', display: isPublicMode ? 'none' : undefined }} onClick={() => { if(!isPublicMode) simRemplac(); }}>⚡ Simuler tous les matchs</button><button className="btn btn-sm btn-sim" style={{ margin:'6px 0', display: isPublicMode ? 'none' : undefined }} onClick={() => { if(isPublicMode) return; const nextDay = days.find(d => allMatches.filter(m => m.day === d).some(m => m.homeGoals === null)); if (nextDay !== undefined) simDay(nextDay); }}>📅 Journée suivante</button>
        </div>

        {subTab === 'classement' && (
          <div>
            <div className="card" style={{ marginBottom:10 }}>
              <div style={{ padding:'8px 12px',display:'flex',gap:12,alignItems:'center',flexWrap:'wrap' }}>
                <input placeholder="🔍 Rechercher..." value={search} onChange={e => setSearch(e.target.value)} style={{ width:220 }} />
                <span style={{ fontSize:12,color:'var(--text-dim)' }}>{cars.length} voitures · {playedCount}/{totalCount} matchs</span>
              </div>
            </div>
            <div className="card">
              <div>
                    {filteredStandings.map(s => {
                      const rank = standings.findIndex(c => c.id === s.id) + 1;
                      const promoted = rank <= 16;
                      const relegated = rank > 48;
                      const rowBg = promoted ? 'rgba(39,174,96,0.07)' : relegated ? 'rgba(192,57,43,0.09)' : 'transparent';
                      const borderColor = promoted ? 'var(--green)' : relegated ? '#e74c3c' : 'transparent';
                      const photo = getCarPhoto(s.id);
                      const diff = s.gf - s.ga;
                      const td = { padding: '0 6px', borderBottom: '1px solid #1a1a1a', background: rowBg, height: 72 };
                                            const badge = promoted ? { label:'▲', bg:'rgba(39,174,96,0.25)', color:'var(--green)' } : relegated ? { label:'⬇', bg:'rgba(192,57,43,0.25)', color:'#e74c3c' } : null;
                      return (
                        <LeaderboardRow key={s.id}
                          rank={rank} rankDiff={null}
                          carId={s.id} leagueName={'Successeurs'}
                          name={s.name} photo={photo} badge={badge}
                          pts={s.pts} w={s.w} d={s.d} l={s.l}
                          gf={s.gf} ga={s.ga} gp={s.gp}
                          borderColor={borderColor}
                          onClick={() => openProfileCar({ leagueName: 'Successeurs', carId: s.id })}
                        />
                      );
                    })})              </div>
              <div style={{ padding:'8px 12px',fontSize:11,display:'flex',gap:12,flexWrap:'wrap',color:'var(--text-dim)' }}>
                <span><span style={{ color:'var(--green)',marginRight:3 }}>■</span>Top 16 → Succ. aux Succ.</span>
                <span><span style={{ color:'var(--text-dim)',marginRight:3 }}>■</span>17-48 → Restent</span>
                <span><span style={{ color:'#e74c3c',marginRight:3 }}>■</span>49-64 → Avant-dernière chance</span>
              </div>
            </div>
          </div>
        )}

        {subTab === 'matchs' && (
          <div>
            <div className="card" style={{ marginBottom:10 }}>
              <div style={{ padding:'8px 12px' }}>
                <input placeholder="🔍 Filtrer par voiture..." value={matchSearch} onChange={e => setMatchSearch(e.target.value)} style={{ width:250 }} />
              </div>
            </div>
            <div className="card">
              <div>
                {days.map(day => {
                  const dayMatches = allMatches.filter(m => m.day === day);
                  const filteredDay = matchSearch
                    ? dayMatches.filter(m => getName(m.homeId).toLowerCase().includes(matchSearch.toLowerCase()) || getName(m.awayId).toLowerCase().includes(matchSearch.toLowerCase()))
                    : dayMatches;
                  if (filteredDay.length === 0) return null;
                  const dayPlayed = dayMatches.filter(m => m.homeGoals !== null).length;
                  const dayComplete = dayPlayed === dayMatches.length;
                  const isOpen = openDay === day;
                  return (
                    <div key={day} style={{ marginBottom:3 }}>
                      <div onClick={() => {
  const scrollY = window.scrollY;
  document.body.style.position = 'fixed';
  document.body.style.top = `-${scrollY}px`;
  document.body.style.width = '100%';
  setOpenDay(isOpen ? null : day);
  requestAnimationFrame(() => {
    document.body.style.position = '';
    document.body.style.top = '';
    document.body.style.width = '';
    window.scrollTo(0, scrollY);
  });
}}
                        style={{ display:'flex',alignItems:'center',gap:8,padding:'7px 10px',cursor:'pointer',borderRadius:isOpen ? '3px 3px 0 0' :3,background:isOpen ? 'rgba(201,168,76,0.1)' :'var(--dark3)',border:`1px solid ${isOpen ? 'var(--gold-dim)' :'var(--border)'}`,transition:'all 0.15s',userSelect:'none' }}>
                        <span style={{ fontFamily:"'Bebas Neue',sans-serif",letterSpacing:2,fontSize:14,color:isOpen ? 'var(--gold)' :'var(--text-dim)' }}>Journée {day}</span>
                        <span style={{ flex:1 }} />
                        {dayComplete
                          ? <span className="badge badge-green" style={{ fontSize:10 }}>✓ Complète</span>
                          : <span className="text-dim" style={{ fontSize:11 }}>{dayPlayed}/{dayMatches.length}</span>}
                        {!dayComplete && (
                          <button className="btn btn-xs btn-sim" style={{ marginLeft:4 }}
                            onClick={e => { e.stopPropagation(); if(isPublicMode) return; const sy = window.scrollY; simDay(day); setOpenDay(day); requestAnimationFrame(() => requestAnimationFrame(() => window.scrollTo(0, sy))); }}>🎲</button>
                        )}
                        <span style={{ color:'var(--text-dim)',fontSize:11,marginLeft:4 }}>{isOpen ? '▲' : '▼'}</span>
                      </div>
                      <div style={{ border:'1px solid var(--gold-dim)',borderTop:'none',borderRadius:'0 0 3px 3px',background:'var(--dark2)',padding:'4px 6px',display:isOpen?'block':'none' }}>
                          {filteredDay.map(m => {
                            const isPlayed = m.homeGoals !== null;
                            const hWin = isPlayed && m.homeGoals > m.awayGoals;
                            const aWin = isPlayed && m.awayGoals > m.homeGoals;
                            const homePhoto = getCarPhoto(m.homeId);
                            const awayPhoto = getCarPhoto(m.awayId);
                            const homeStats = getCarStats(m.homeId, allMatches);
                            const awayStats = getCarStats(m.awayId, allMatches);
                            const homeRank = standings.findIndex(s => s.id === m.homeId) + 1;
                            const awayRank = standings.findIndex(s => s.id === m.awayId) + 1;
                            const homePts = standings.find(s => s.id === m.homeId)?.pts ?? 0;
                            const awayPts = standings.find(s => s.id === m.awayId)?.pts ?? 0;
                            return (
                              <div key={m.id}
                                onClick={() => openMatchModal({
                                  homeName: getName(m.homeId), awayName: getName(m.awayId),
                                  homePhoto, awayPhoto,
                                  homeGoals: m.homeGoals, awayGoals: m.awayGoals,
                                  homeStats, awayStats,
                                  homeRank, awayRank, homePts, awayPts,
                                  homeQual: null, awayQual: null,
                                  onConfirm: (hg, ag) => updateMatch(m.id, hg, ag),
                                })}
                                style={{ display:'flex',alignItems:'center',gap:8,padding:'8px 10px',borderBottom:'1px solid #1a1a1a',cursor:'pointer',borderLeft:isPlayed ? '3px solid var(--green)' :'3px solid transparent',background:isPlayed ? 'rgba(39,174,96,0.03)' :'transparent',borderRadius:3,transition:'background 0.1s' }}>
                                <div style={{ flex:1,display:'flex',alignItems:'center',gap:6,justifyContent:'flex-end' }}>
                                  <div style={{ fontSize:12,fontWeight:600,textAlign:'right',color:hWin ? 'var(--green)' :aWin ? 'var(--text-dim)' :'var(--text)',lineHeight:1.2 }}>{getName(m.homeId)}</div>
                                  <CarThumb photo={homePhoto} size={40} />
                                </div>
                                <div style={{ fontFamily:"'Bebas Neue',sans-serif",fontSize:20,flexShrink:0,minWidth:52,textAlign:'center',letterSpacing:2,display:'flex',alignItems:'center',justifyContent:'center',gap:2 }}>
                                  {isPlayed ? (
                                    <>
                                      <span style={{ color:hWin ? 'var(--green)' :aWin ? '#e74c3c' :'var(--gold)' }}>{m.homeGoals}</span>
                                      <span style={{ color:'var(--text-dim)' }}> : </span>
                                      <span style={{ color:aWin ? 'var(--green)' :hWin ? '#e74c3c' :'var(--gold)' }}>{m.awayGoals}</span>
                                    </>
                                  ) : <span style={{ color:'var(--text-dim)' }}>— : —</span>}
                                </div>
                                <div style={{ flex:1,display:'flex',alignItems:'center',gap:6 }}>
                                  <CarThumb photo={awayPhoto} size={40} />
                                  <div style={{ fontSize:12,fontWeight:600,color:aWin ? 'var(--green)' :hWin ? 'var(--text-dim)' :'var(--text)',lineHeight:1.2 }}>{getName(m.awayId)}</div>
                                </div>
                              </div>
                            );
                          })}
                        </div>
                    </div>
                  );
                })}
              </div>
            </div>
          </div>
        )}
      </div>
    );
  }

